/* Cendrelame · data/notes-de-version.js */
const PATCH=[
 {"v": "0.8.21", "t": "Images du Paladin", "sec": [["Amélioré", ["Le Paladin a ses vraies images : apparence 1 (homme) et apparence 2 (femme), en armure argent et or avec bouclier au soleil et marteau. Avant : un Guerrier recoloré en bleu."]], ["Nouveau", ["2 apparences de Paladin dans Communauté → Personnalisation → Apparence du héros : Gardien de l’Aube (armure blanche et or, grand bouclier lumineux) et Héraut du Jugement (armure sombre et rouge, marteau entouré d’éclairs dorés)."]]]},
 {"v": "0.8.20", "t": "Failles temporelles et objets d’Ensemble", "sec": [["Nouveau", ["Failles temporelles : nouveau mode dans Aventure → Failles, ouvert au niveau 50. Choisissez un rang, entrez dans la faille et enchaînez 3 combats puis le boss. Vos PV ne remontent pas entre les combats et vous ne pouvez boire que 5 potions pour toute la faille.", "10 rangs : refermer la faille d’un rang (battre son boss) ouvre le suivant. Les ennemis sont comparés au mode Mythique : rang 1 → PV −20 % et dégâts −32 % ; rang 5 → PV +28 % et dégâts +1 % ; rang 10 → PV +88 % et dégâts +41 %. Le boss a 20 % de PV en plus. Le décor et les ennemis changent selon le rang.", "Butin des failles : beaucoup d’or (rang 1 : 2 500 par combat et 10 000 sur le boss ; rang 10 : 7 000 et 32 500), des ressources de la zone, des Pierres de renforcement, des Runes de pierre et parfois une Pierre épique ou un Prisme divin sur le boss. Équipement niveau 85 : 45 % par combat, 2 objets garantis sur le boss.", "Si vous tombez, vous gardez le butin des combats déjà gagnés.", "Objets d’Ensemble (nouvelle rareté verte), uniquement dans les failles : 2 ensembles par classe, un par spécialisation, de 6 pièces (arme, heaume, armure, jambières, bottes, amulette). Bonus à 2, 4 et 6 pièces portées, actifs avec la bonne spécialisation. Exemple, Verdict solaire (Paladin, Tempête divine) : 2 pièces → +12 % de Force ; 4 → +8 % de dégâts sacrés ; 6 → Zèle maximum +2 et Verdict +40 %.", "Chance d’Ensemble : boss 15 % au rang 1 → 37,5 % au rang 10 ; combats 3 % → 7,5 %. 70 % de chances que ce soit l’ensemble de votre spécialisation.", "Ensembles : Fureur de l’Ancien Roi et Bastion d’Airain (Guerrier), Cendres de l’Éternel et Orage captif (Sorcier), Égide de l’Aube et Verdict solaire (Paladin)."]]]},
 {"v": "0.8.19", "t": "Nouvelle classe : le Paladin", "sec": [["Nouveau", ["Paladin : chevalier sacré qui utilise la Force. Il porte marteaux, grands heaumes, harnois, cuissards et solerets. Statistiques de départ : 310 PV, 13 Force, 11 Défense, 8,5 Vitesse (un peu plus solide que le Guerrier, un peu moins de dégâts).", "Nouvel élément Sacré pour ses sorts. Compétences de base : Jugement, Bouclier béni (bouclier + soin sur la durée), Consécration (zone) et Aura du croisé (+10 % de Force pendant 15 tours).", "Spécialisation Rempart Sacré : boucliers, soins et provocation. Ressource Bénédiction : +1 par coup reçu (5 au maximum) ; chaque point réduit de 2 % les dégâts subis et soigne 1 % des PV max au début du tour. Exemple : à 5 Bénédictions, −10 % de dégâts subis et 5 % de PV rendus chaque tour. Ultimes : Bouclier divin, Lumière céleste, Marteau du jugement.", "Spécialisation Tempête divine : dégâts sacrés. Ressource Zèle : +1 à chaque sort sacré (5 au maximum), +3 % de dégâts sacrés par point. Verdict et Jugement dernier consomment tout le Zèle. Exemple : Verdict à 5 Zèle → 80 % + 5 × 25 % = 205 % de la Force. Ultimes : Jugement dernier, Ailes de la vengeance, Tempête divine.", "La Potion de force sert aussi au Paladin. L’Hôtel des ventes a un filtre Paladin. Nouveau dossier d’apparences : assets/img/skins/paladin/."]]]},
 {"v": "0.8.18", "t": "Cosmétiques Prodiges", "sec": [["Nouveau", ["Collection Prodiges : 19 nouveaux cosmétiques. 6 auras plus détaillées (Ailes du phénix, Vortex du néant, Cercle arcanique, Prismes en orbite, Souffle sylvestre, Auréole dorée), 5 effets de carte (Étoiles filantes, Orage, Aurore boréale, Pluie d’or, Runes flottantes), 3 cadres de portrait, 1 ornement, 2 traînées et 2 arrière-plans.", "Coffre des Prodiges : contient 1 cosmétique Prodiges (Rare 50 %, Épique 38 %, Légendaire 12 %), un cosmétique pas encore obtenu en priorité. En vente chez le Marchand (Cosmétiques) pour 60 000 or + 1 Rune ancienne. Clic droit dans le sac pour l’ouvrir.", "Le Coffre des Prodiges peut aussi tomber en Défi après une victoire : 3 % au palier 0, puis +0,5 % par palier. Exemples : palier 4 → 5 % ; palier 14 et plus → 10 %.", "10 nouvelles apparences du héros : Berserker, Défenseure et Saison 1 pour le Guerrier ; Évocatrice, Évocateur, Pyromancienne, Pyromancien et 3 apparences Saison 1 pour le Sorcier."]], ["Amélioré", ["Personnalisation : tous les cosmétiques sont rangés par catégorie. Avant : une seule liste mélangée. Après : Base, Saison 1, Duel, Prodiges (et Base, Spécialisations, Saison 1 pour les apparences).", "Décors des zones de combat plus nets sur toute la hauteur : images refaites en plus grande taille et cadrées sur le milieu du paysage. Avant : seul le bas était net, le haut flouté. Après : toute l’image est nette.", "Fenêtre des amis déplaçable sur PC : glissez le titre « Amis » pour la placer où vous voulez ; elle garde sa place. Double-clic sur le titre : retour à sa place d’origine.", "Écran d’accueil : le héros est un peu plus petit (environ 10 %) pour laisser respirer le décor."]]]},
 {"v": "0.8.17", "t": "Progression plus longue et apparences", "sec": [["Équilibrage", ["Les niveaux demandent plus d’expérience, de plus en plus en montant. Exemples : niveau 10 → 11 : 1 194 → 2 531 XP ; niveau 30 → 31 : 6 927 → 17 305 XP ; niveau 49 → 50 : 15 186 → 40 837 XP. Au total, monter au niveau 50 demande environ 2,5 fois plus d’expérience.", "Moins d’équipement en Aventure : chance d’équipement par combat divisée par deux environ. Exemples : Forêt des Murmures 18 % → 8 % ; Abysses du Néant 26 % → 12 % (boss : 78 % → 36 %). Le butin des Défis ne change pas.", "Gains hors ligne : 1 combat toutes les 3 minutes au lieu de 2. Exemple : 6 h d’absence → 120 combats au lieu de 180. Jusqu’à 20 objets d’équipement gardés en attente (au lieu de 40) ; les autres sont recyclés."]], ["Nouveau", ["Apparence du héros : nouvelle catégorie dans Communauté → Personnalisation pour changer l’apparence de votre personnage. Elle s’affiche partout : accueil, combat, duel, sélection.", "Les nouvelles apparences ajoutées au jeu sont débloquées pour l’instant."]], ["Amélioré", ["Décors plus nets : l’image n’est plus agrandie au-delà de la largeur de l’écran ; le haut est complété par un fond flouté, comme une profondeur de champ.", "Défis : le décor correspond maintenant au boss choisi (Colosse de Braise → Pic de Cendre, Wyrm des Glaces → glaces, Avatar de l’Abîme → Abysses) au lieu de l’arène des duels."]]]},
 {"v": "0.8.16", "t": "Sac simplifié", "sec": [["Équilibrage", ["Le Sac agrandi est retiré : l’inventaire revient à 14 × 5 cases (70) pour tout le monde. Exemple : sac de 98 cases → 70 cases.", "Vos achats du Sac agrandi sont remboursés : or et runes. Exemple : niveaux 1 et 2 achetés → 105 000 or + 1 Rune ancienne.", "Les objets qui ne tiennent plus dans le sac sont rangés dans le coffre du compte ; s’il n’y a vraiment plus de place, ils sont vendus.", "Les sacoches (artisanat, potions, Compagnon) ne changent pas."]], ["Amélioré", ["Tout l’équipement, armes comprises, occupe maintenant 2 cases en hauteur dans le sac et le coffre. Exemple : arme 1 × 5 → 1 × 2, armure 2 × 3 → 1 × 2. Les anneaux et l’amulette restent sur 1 case.", "Salle du héros : le personnage s’affiche seul, sans les emplacements d’équipement autour.", "Carte de joueur : seuls vos 3 personnages de plus haut niveau apparaissent, et la carte garde toujours la même taille."]]]},
 {"v": "0.8.15", "t": "Salle du héros et gains hors ligne", "sec": [["Nouveau", ["Écran d’accueil « Salle du héros » : après le choix du personnage, vous arrivez sur votre héros au lieu de la carte des zones. Il est accessible à tout moment avec le médaillon Accueil (menu Plus sur téléphone).", "Au centre : votre héros en grand, entouré de son équipement porté (survolez un objet pour voir sa fiche), avec ses PV, sa statistique principale et sa puissance.", "À droite : le prochain boss de votre progression, des raccourcis vers Aventure, Défis et Duel, et une liste « À faire » (gains hors ligne, quêtes, expéditions de compagnon, points de compétence, nouveaux objets, trophées).", "Gains hors ligne : pendant votre absence, votre héros continue de combattre à sa progression actuelle (difficulté Normale). 1 combat toutes les 2 minutes, à partir de 5 minutes d’absence, jusqu’à 12 heures. Exemple : 6 h d’absence → 180 combats.", "En cliquant sur Récupérer, une fenêtre affiche tout ce qui a été gagné : or, expérience, ressources, potions et chaque objet d’équipement ajouté au sac. Les objets refusés par votre filtre de butin (ou si le sac est plein) sont recyclés automatiquement."]]]},
 {"v": "0.8.14", "t": "Interface plein écran", "sec": [["Nouveau", ["Le jeu occupe maintenant toute la fenêtre du navigateur : plus de grand bloc au centre.", "En Aventure, le décor de la zone remplit l’écran et la carte des zones s’affiche directement dessus, avec la fiche de la zone à droite.", "Le menu principal passe sur la gauche, en médaillons hexagonaux dorés. Le bouton Amis rejoint l’en-tête, à côté de la Messagerie ; le Sac reste en bas à gauche.", "Nouveau style de boutons « gravé doré » : coins coupés, liseré d’or, double filet sur les boutons principaux comme Combattre."]], ["Amélioré", ["Les écrans (Marchand, Amélioration, Quêtes, Communauté…) s’agrandissent pour utiliser toute la place disponible.", "En combat, la scène s’étire sur toute la hauteur et les personnages sont plus grands. Exemple : sur un écran 1440 × 900, scène 432 px → environ 600 px de haut.", "Le Sac et le coffre s’ouvrent sous l’en-tête, sans recouvrir le menu."]]]},
 {"v": "0.8.13", "t": "Détourage des images", "sec": [["Correction", ["Guerrier : la lame de l’épée n’est plus trouée (ses reflets blancs avaient été effacés avec le fond).", "Contours plus propres sur tous les personnages, ennemis et icônes : plus de liseré blanc autour du trait noir.", "Les petits espaces blancs restés entre un bras et le corps sont maintenant transparents."]]]},
 {"v": "0.8.12", "t": "Nouveau style : premières images", "sec": [["Nouveau", ["Nouveaux décors pour les 5 zones, l’arène des défis et la zone de glace.", "Nouvelles apparences en pied pour le Sorcier, et deux apparences pour le Guerrier (homme et femme) : elles se choisissent à la création du personnage.", "Gobelin, Chaman gobelin et Roi Gobelin ont leur nouvelle image, en combat comme sur la carte.", "Nouvelles icônes pour toutes les potions, toutes les ressources, les runes, gemmes, parchemins et pierres, ainsi que pour la nourriture, les tickets, les pierres d’évolution et les objets du Compagnon."]], ["Amélioré", ["En combat, les ennemis sont un peu plus petits que le héros et les boss plus grands. Exemple : Roi Gobelin, même taille que le héros → environ un tiers plus grand qu’un Gobelin.", "Ordre du tour et liste des ennemis de la zone : l’ennemi apparaît en buste au lieu d’un symbole.", "Icônes d’objets un peu plus grandes dans le sac.", "Écran de sélection et de création : le personnage est affiché en entier."]]]},
 {"v": "0.8.11", "t": "Réorganisation du jeu", "sec": [["Technique", ["Le jeu n’est plus un seul gros fichier : il est réparti en dossiers et fichiers par thème (classes, objets, combat, forge, quêtes, Compagnon, interface…). Rien ne change en jeu.", "Préparation du nouveau style vectoriel flat : chaque ennemi, objet, ressource, potion, compétence, créature et classe peut maintenant recevoir sa propre image. Tant qu’une image n’est pas fournie, le dessin actuel reste affiché.", "Les images intégrées (portraits, fonds de zones) sont devenues de vrais fichiers : le jeu se charge plus vite et le navigateur les garde en mémoire."]]]},
 {"v": "0.8.10", "t": "Butin selon la difficulté et le palier", "sec": [["Pierre de remodelage", ["L’affixe change maintenant toujours de type à l’intérieur de son groupe, avec une nouvelle valeur. Exemple : Chance de critique → Dégâts critiques ou Intelligence (groupe Fureur) ; Résistance au feu → une autre résistance ; PV → PV %.", "La statistique principale (Force ou Intelligence principale) garde son type et change seulement de valeur."]], ["Équilibrage", ["Résistances (physique, magique et élémentaires) : plafond 75 % → 50 %, pour les joueurs comme pour les ennemis."]], ["Butin", ["Héroïque : chances de butin ×1,5 et raretés plus hautes. Exemple, Abysses du Néant : équipement 26 % → 39 % par combat, part de Légendaire 1,5 % → environ 3 %.", "Mythique : chances de butin ×3 (avant ×2) et raretés encore plus hautes (part de Légendaire environ 6 %, presque plus d’objets communs).", "Défis, à chaque palier : runes, essences et cristaux +5 % par palier ; nouvel équipement bonus avec 2 % de chance par palier (30 % au maximum) en plus de l’équipement garanti.", "Défis : Cristal d’ascension 3 % + 0,5 → 0,6 % par palier (max 10 → 15 %) ; Coffre des Reliques 1 % + 0,5 → 0,6 % par palier (max 10 → 15 %) ; Pierre de remodelage 5 % + 0,5 → 0,75 % par palier (max 15 → 25 %). Exemple au palier +10 : Cristal 8 → 9 %, Remodelage 10 → 12,5 %, équipement bonus 20 %."]]]},
 {"v": "0.8.9", "t": "Duels : dégâts réduits", "sec": [["Équilibrage", ["Duels : tous les dégâts infligés entre joueurs sont réduits de 65 % (coups, critiques, contre-attaques, brûlures, saignements et poisons). Exemple : un coup à 6 000 contre un boss fait environ 2 100 à un joueur.", "Le vol de vie suit les dégâts réduits. Les PV de duel ne changent pas (2,5 × vos PV).", "Simulation au niveau 50 en équipement légendaire +6 : un duel durait 4 à 5 tours, il dure maintenant 12 à 18 tours.", "Aventure, défis et boss ne changent pas."]]]},
 {"v": "0.8.8", "t": "Affixes selon l’emplacement", "sec": [["Équilibrage", ["Les affixes dépendent maintenant de l’emplacement de l’objet, un peu comme dans Diablo 4.", "Bijoux (anneaux et amulette) : affixes d’attaque (Force, Intelligence, Chance et Dégâts critiques, Dégâts bonus) ×1,5 ; PV, PV % et Défense ×0,75 ; résistances ×0,75. Exemple, anneau épique niveau 50 : Intelligence jusqu’à 46 → 70, PV jusqu’à 600 → 450.", "Armures (casque, torse, jambes, bottes) : PV, PV % et Défense ×1,15 ; résistances ×1,25 ; affixes d’attaque ×0,7. Exemple, casque épique niveau 50 : résistance au feu jusqu’à 13 % → 16 %, Intelligence jusqu’à 46 → 33.", "Arme : inchangée. Vitesse, Esquive, Vol de vie et Or trouvé : inchangés partout.", "Au total, un équipement complet garde à peu près la même puissance (environ +2 % d’attaque, −2 % de PV) : l’attaque se concentre sur les bijoux, la défense sur les armures. Vos objets actuels sont mis à jour automatiquement, et les parchemins suivent la même règle."]], ["Équipement", ["Pouvoirs des objets divins : l’infobulle affiche directement la valeur divine (par exemple Vitalité : +10 % de PV max sur un objet légendaire, +15 % sur un objet divin). L’Aide montre les deux valeurs côte à côte."]], ["Pierre de remodelage", ["Ajoutée au Livre des recettes.", "Nouveau butin des défis : 5 % par victoire au palier +0, puis +0,5 % par palier (15 % au maximum).", "Aventure : elle peut tomber dans toutes les zones (0,2 % à 0,8 % par combat), et 3 fois plus souvent sur les boss (0,6 % à 2,4 %)."]], ["Correction", ["Livre des recettes : la Pierre de rareté indique +15 % (au lieu de +5 %), le Prisme divin 1 à 10 prismes à 10 % chacun, et la Pierre de renforcement 2 pierres à partir de +6."]]]},
 {"v": "0.8.7", "t": "Pouvoirs légendaires et Pierre de remodelage", "sec": [["Équipement", ["Nouveaux pouvoirs légendaires : Garde des éléments (+5 % à toutes les résistances élémentaires) et Vitalité (+10 % de PV max).", "Œil du prédateur : +6 % → +3 % de chances de critique, +10 % → +7 % de dégâts critiques.", "Objets divins : ils ont maintenant eux aussi un pouvoir, 50 % plus fort. Exemples : Vitalité +10 % → +15 % de PV max, Brise-armure 6 % → 9 %. Moisson ne change pas.", "Tous vos objets légendaires et divins déjà obtenus (portés, dans le sac ou dans le coffre) reçoivent un pouvoir tiré au hasard parmi les 12. Ceux qui en avaient déjà un depuis la 0.8.6 le gardent."]], ["Forge", ["Nouvel objet : Pierre de remodelage (Épique). Choisissez une affixe de l’objet : elle est remplacée par une affixe tirée au hasard dans la même catégorie (Robustesse, Fureur, Adresse, Vie ou Autres), avec une nouvelle valeur. Réussite 100 %. Coût : 1 500 or + 30 or par niveau d’objet.", "Une affixe déjà présente sur l’objet ne peut pas sortir. Les affixes de fusion (+1 PA) ne se remodèlent pas ; la statistique principale garde son type mais change de valeur.", "Où la trouver : chez le Marchand (catégorie Enchantement, 15 000 or + 1 Rune majeure) ou en aventure dans les zones 3 à 5 (0,2 à 0,6 % par combat, ×3 sur les boss)."]], ["Équilibrage", ["Parchemin d’Adresse : il ne peut plus donner de Points d’action. Chances : Vitesse 35 → 37 %, Esquive 35 → 37 %, Vol de vie 25 → 26 %. Les affixes PA déjà obtenues sont conservées."]]]},
 {"v": "0.8.6", "t": "Pouvoirs légendaires", "sec": [["Équilibrage", ["Dégâts critiques : plafond 200 % → 300 %. Un coup critique peut maintenant infliger jusqu’à 3 fois les dégâts (avant : 2 fois)."]], ["Équipement", ["Nouveau : 10 pouvoirs légendaires. Chaque nouvel objet légendaire en reçoit un au hasard (avant : toujours +6 % de critique et +10 % de dégâts critiques).", "Œil du prédateur : +6 % de chances de critique et +10 % de dégâts critiques. Brise-armure : ignore 6 % de la Défense ennemie. Représailles : 8 % de chance de contre-attaquer quand vous êtes touché. Opportuniste : +8 % de dégâts contre les cibles étourdies, paralysées ou ralenties.", "Soif de survie : +4 % de vol de vie sous 50 % de PV. Dernier rempart : −8 % de dégâts subis sous 35 % de PV. Fureur du désespoir : +1 % de dégâts par tranche de 10 % de PV manquants. Égide : boucliers et barrières +15 %. Sève ancienne : rend 1 % des PV max à chaque tour. Moisson : vaincre un ennemi rend 1 PA.", "Un même pouvoir se cumule sur 3 objets au maximum (Moisson : un seul). Vos objets légendaires actuels gardent leur pouvoir (Œil du prédateur). Le pouvoir s’affiche dans l’infobulle de l’objet et dans l’Aide."]]]},
 {"v": "0.8.5", "t": "Place du marché et Maroquinier", "sec": [["Marchand", ["Le Marchand devient la Place du marché : un accueil avec trois échoppes, puis un bouton pour revenir à la place.", "Nouveaux décors propres au commerce : le marché et ses étals, la salle des enchères, l’atelier du maroquinier (avant : décor de l’arène de duel)."]], ["Hôtel des ventes", ["L’Hôtel des ventes déménage de Communauté vers la Place du marché. Il fonctionne comme avant (Acheter, Vendre, Mes ventes, Historique)."]], ["Maroquinier", ["Nouvelle échoppe pour agrandir son stockage. Les améliorations valent pour tout le compte.", "Sac agrandi : +1 rangée de 14 cases par niveau. Sac : 70 → 84 → 98 → 112 cases. Prix : 25 000 or ; 80 000 or + 1 Rune ancienne ; 200 000 or + 1 Rune primordiale.", "Sacoche d’artisanat : 8, 16 puis 24 piles de 500 pour la poudre, les essences, les runes, les pierres, les parchemins, les bonus de réussite et les prismes. Prix : 15 000 or ; 50 000 or + 1 Rune majeure ; 120 000 or + 1 Rune ancienne.", "Ceinture de potions : 6 puis 12 piles pour toutes les potions. Prix : 20 000 or ; 60 000 or + 1 Rune majeure.", "Besace du dresseur : 8 puis 16 piles pour les objets de Compagnon. Prix : 15 000 or ; 45 000 or + 1 Rune majeure.", "Les objets compatibles vont automatiquement dans leur sacoche, sans prendre de place dans le sac, et restent utilisables partout (Forge, combat, Compagnon, quêtes).", "Nouveau bouton Sacoches dans l’inventaire, à côté du coffre : voir leur contenu, remettre une pile dans le sac d’un clic, ou tout ranger avec « Ranger le sac »."]]]},
 {"v": "0.8.4", "t": "Forge : équipement porté", "sec": [["Forge", ["Quand l’enclume est vide, le panneau de droite affiche maintenant votre équipement porté comme dans l’inventaire : le personnage au centre et ses 8 emplacements autour. Un clic sur un objet le pose sur l’enclume.", "La liste de l’équipement du sac reste juste en dessous."]]]},
 {"v": "0.8.3", "t": "Hôtel des ventes et défis en boucle", "sec": [["Hôtel des ventes", ["Filtre « Niveau d’objet » : maximum 60 → 75, pour trouver les objets des défis (niveau 65 et 70) et ceux élevés par un Cristal d’ascension."]], ["Défis", ["Avec « Rejouer » activé (engrenage à côté de Combattre), le butin d’un défi gagné est récupéré automatiquement : plus de fenêtre à fermer. Un message résume l’or et l’équipement obtenus.", "Le même défi, au même palier, est ensuite relancé tout seul. Une défaite arrête la boucle, comme en aventure."]]]},
 {"v": "0.8.2", "t": "Prismes, raretés et défis", "sec": [["Forge", ["Prisme divin : placez de 1 à 10 prismes pour faire passer un objet légendaire en Divin. Chaque prisme donne 10 % de réussite : 5 prismes = 50 %, 10 prismes = 100 %. Avant : 1 prisme, réussite garantie.", "Tous les prismes placés sont consommés. En cas d’échec, l’objet reste légendaire et intact.", "Renforcement : il faut maintenant 2 Pierres de renforcement à partir du passage +5 → +6. Pour aller de +0 à +10 : 10 → 15 pierres.", "Atelier de la Forge : l’équipement du sac s’affiche en liste (nom, rareté, niveau) sous « Objets portés ». Un clic le pose sur l’enclume."]], ["Équilibrage", ["Puissance des raretés : chaque rareté ajoute maintenant 15 % au lieu de 5 %. Magique ×1,05 → ×1,15 ; Rare ×1,10 → ×1,30 ; Épique ×1,15 → ×1,45 ; Légendaire ×1,20 → ×1,60 ; Divin ×1,25 → ×2,10.", "Exemple : une affixe +100 Force sur un objet légendaire passe à +133. Vos objets actuels sont mis à jour automatiquement.", "Mode Héroïque : le butin d’équipement est maintenant de niveau 60 (avant : 50). Le niveau des monstres ne change pas.", "Défis : les boss infligent 30 % de dégâts en plus. Colosse de Braise au palier +0 : Force 309 → 402.", "Potion d’oubli : 15 000 or + 5 Prismes divins → 5 000 or."]], ["Défis", ["Nouvelle interface identique à la campagne : carte des boss, paliers en frise, butin en icônes et bouton Combattre.", "Nouveau bouton Infos (icône) : statistiques du boss au palier choisi, résistances, compétences détaillées et règles du combat.", "Nouveau : chaque victoire donne 1 équipement garanti, de niveau 65 aux paliers +0 à +9 et de niveau 70 à partir du palier +10 (70 est le maximum du butin). Rareté : Rare, Épique ou Légendaire, avec plus d’Épiques et de Légendaires à chaque palier.", "Le niveau requis pour porter ces objets reste 50. Le Cristal d’ascension peut encore ajouter +5 niveaux d’objet, une fois par objet.", "Le mode à deux joueurs est retiré : les défis se jouent seul. Les boutons « Raid » des amis disparaissent."]], ["Aventure", ["Butin plus lisible : une seule icône pour l’équipement et une par famille de composants (runes, essences, pierres de rareté…). L’infobulle détaille chaque rareté et chaque objet avec ses chances."]], ["Talents", ["Nouveau : une réinitialisation gratuite des talents par personnage (bouton « Réinitialiser (gratuit) »). Les suivantes demandent une Potion d’oubli."]], ["Duels", ["Nouveau : 7 cosmétiques de duel, permanents et non liés à la saison : Lames croisées (5 victoires), Sable de l’arène (10), Couronne du champion (20), Étincelles d’acier (35), Esprit du gladiateur (50), Trophée du champion (75) et l’arrière-plan Grande arène (100).", "Ils se débloquent automatiquement avec vos victoires en duel (comptées sur tout le compte). Leur progression s’affiche dans l’onglet Duel, et ils portent l’étiquette « Duel » dans la Personnalisation."]], ["Aide", ["Aide beaucoup plus détaillée, avec un sommaire : rage et difficultés, butin de chaque zone avec ses taux, raretés et affixes (affixe bonus 12 % sur les Rares et Épiques), Forge, enchantement, recyclage, potions, talents, défis, duels, Compagnon, quêtes et coffres."]]]},
 {"v": "0.8.1", "t": "Version téléphone", "sec": [["Téléphone", ["Le jeu s’adapte aux écrans de téléphone (version PC inchangée).", "Nouvelle barre de navigation en bas : Sac, Compagnon, Aventure, Quêtes et Plus. « Plus » ouvre un menu avec le Marchand, l’Amélioration, le Personnage, la Communauté, les Trophées, les Amis, la Messagerie et les Options.", "En-tête compact : portrait à gauche, titre et saison au centre, menu à droite.", "L’inventaire s’ouvre en plein écran, avec une grille ajustée à la largeur. Toucher un objet affiche sa fiche et ses boutons en bas de l’écran.", "Appui long = clic droit (équiper, ouvrir un coffre, utiliser un ticket, placer à la Forge…). Sur un élément sans action, l’appui long affiche son infobulle.", "Les menus latéraux (Quêtes, Communauté, Compagnon, ateliers) deviennent un bandeau horizontal. La Forge masque son aide pour laisser la place à l’enclume.", "Compagnon : créatures sur 2 colonnes, fiche en plein écran avec un bouton pour la fermer. Marchand : 3 objets par ligne."]]]},
 {"v": "0.8.0", "t": "Le mode Compagnon", "sec": [["Compagnon", ["La Collecte disparaît et laisse place au Compagnon : invoquez des créatures, nourrissez-les, faites-les évoluer et envoyez-les en expédition.", "10 espèces de 5 types (Feu, Eau, Terre, Ténèbres, Lumière), chacune avec 3 formes : la 2ᵉ au niveau 20 et la 3ᵉ au niveau 40, avec une Pierre d’évolution de son type.", "Chaque créature a des statistiques (Vie, Attaque, Attaque magique, Défense physique, Défense magique, Esquive) et 3 passifs tirés au hasard. Sa qualité va de D à S : les créatures S sont très rares (environ 1 sur 200).", "Créatures Shiny : 0,5 % de chance. Elles gardent leur type mais ont toutes leurs statistiques au maximum, avec 15 % de plus ; leurs passifs restent aléatoires.", "Tickets de découverte (clic droit dans l’inventaire) : invocation par 1 ou par 10. Ticket normal : Commune 62 %, Rare 28 %, Épique 8,5 %, Légendaire 1,5 %. Ticket supérieur : Rare 60 %, Épique 32 %, Légendaire 8 %.", "Stockage de 30 créatures, agrandissable par 10 jusqu’à 100. Relâchez une créature (bouton sur le côté de sa carte) ou plusieurs à la fois pour gagner des Jetons de ménagerie.", "Cadeau de bienvenue : 3 Tickets de découverte et 5 Croquettes à la première visite."]], ["Expéditions", ["5 expéditions de 1 h à 24 h, renouvelées toutes les 6 heures, avec 1 à 3 places. Une expédition peut partir même avec une seule créature.", "La réussite dépend des statistiques demandées, du type (Eau bat Feu, Feu bat Terre, Terre bat Eau ; Lumière et Ténèbres l’une contre l’autre : ±20 %), du niveau et de la faim.", "Butin : or, ressources d’artisanat, Jetons de ménagerie et, plus rarement, une Pierre d’évolution. En cas d’échec : 25 % du butin et la moitié de l’expérience."]], ["Faim", ["La faim baisse de 1 % par heure, 2 % en expédition. Malus sur les statistiques en expédition : aucun à partir de 75 %, −20 % entre 50 et 74 %, −40 % entre 25 et 49 %, −60 % en dessous."]], ["Boutique du dresseur", ["Nourriture (Croquettes, Ragoût, Festin), Tickets de découverte, Pierres d’évolution, 10 objets portés (1 par créature), places de stockage et 6 habitats (cosmétiques du mode, hors saison).", "Au Marchand : Ticket de découverte (prix selon votre niveau), Ticket supérieur (60 000 or + 1 Rune ancienne), Croquettes et Ragoût."]], ["Quêtes et trophées", ["Les quêtes « Récolter à la Mine » deviennent « Réussir des expéditions de compagnon ».", "La catégorie de trophées Collecte devient Compagnon, avec 4 nouveaux trophées ; ceux que vous aviez déjà obtenus restent acquis."]], ["Interface", ["Le parchemin des nouveautés présente un récapitulatif des grandes mises à jour manquées si vous n’êtes pas venu depuis longtemps."]], ["Bientôt", ["Duels de créatures contre les autres joueurs : visibles mais pas encore disponibles."]]]},
 {"v": "0.7.10", "t": "Coffres au clic droit et sac de combat", "sec": [["Coffres", ["Les coffres de saison arrivent maintenant dans l’inventaire (récompenses de quêtes et achats au Marchand) : faites un clic droit dessus pour les ouvrir, comme le Coffre des Reliques.", "Tous les coffres utilisent la même animation de roulette, et chaque coffre donne 1 cosmétique.", "Les coffres de saison que vous aviez déjà sont placés automatiquement dans l’inventaire."]], ["Sac de combat", ["Nouvelles limites : 3 potions de chaque sorte pour les potions de vie (petite, normale et grande), 1 pour toutes les autres (avant : 10 Potions de vie, 3 Potions de résistance, de force ou d’intelligence, 2 Potions d’action). Les potions en trop retournent dans l’inventaire."]]]},
 {"v": "0.7.9", "t": "Potions de soin, Cristal d’ascension et Fusion", "sec": [["Potions", ["Nouvelles potions de soin chez le Marchand : Petite potion de vie (rend 20 % des PV max, recharge 3 tours), Potion de vie (40 %, inchangée) et Grande potion de vie (65 %, recharge 5 tours).", "Nouvelles potions de soin sur la durée : Potion de régénération (6 % des PV max par tour pendant 4 tours, 24 % au total) et Élixir de régénération (10 % par tour pendant 5 tours, 50 % au total)."]], ["Marchand", ["Nouvelle catégorie Cosmétiques : Coffre des Reliques (60 000 or + 1 Rune primordiale), Coffre de saison épique (40 000 or + 1 Rune ancienne) et Coffre de saison légendaire (60 000 or + 1 Rune primordiale)."]], ["Forge", ["Nouvel objet légendaire, le Cristal d’ascension : il augmente de 5 le niveau d’objet d’un équipement et recalcule toutes ses affixes (une seule fois par objet ; le niveau requis ne change pas). Il s’obtient uniquement en réussissant des défis de raid (3 % au palier +0, puis +0,5 % par palier, jusqu’à 10 %).", "Nouvelle Fusion légendaire à l’Autel d’enchantement : 10 Prismes divins + 3 Runes primordiales + 1 Parchemin vierge + 20 000 or donnent un Parchemin d’action, qui ajoute +1 Point d’action à un anneau sans prendre d’emplacement d’affixe.", "Nouveau bouton « Recettes » dans les ateliers : la liste complète des recettes d’enchantement, de fusion et d’amélioration."]], ["Cosmétiques", ["Les auras de combat passent maintenant à la fois derrière et devant le héros."]], ["Correction", ["Quête de saison « Créer 10 équipements » remplacée par « Recycler 50 objets » : la création d’équipement n’est pas disponible pour l’instant.", "Les Points d’action donnés par une affixe ne sont plus multipliés par le niveau de renforcement de l’objet (ils restent des nombres entiers)."]]]},
 {"v": "0.7.8", "t": "Cartes de joueur fixes", "sec": [["Interface", ["Les cartes de joueur ne s’inclinent plus et ne brillent plus quand la souris passe dessus (carte, bannière du classement et carte flottante)."]]]},
 {"v": "0.7.7", "t": "Options : revoir les nouveautés", "sec": [["Interface", ["Nouveau bouton dans Options → Interface : « Revoir les nouveautés » réaffiche le parchemin de la dernière grande mise à jour, même si vous l’aviez masqué."]]]},
 {"v": "0.7.6", "t": "Saison : quêtes, cosmétiques et trophées", "sec": [["Quêtes", ["Nouvelle page des quêtes avec une barre latérale : Quêtes journalières, Quêtes hebdomadaires, puis la saison en cours.", "Nouvelles quêtes de saison : elles restent toute la saison et ne se renouvellent pas (vaincre des boss de campagne en Héroïque et en Mythique, créer des équipements, renforcer un objet jusqu’à +7, enchanter des parchemins, remporter des duels, vaincre l’Avatar de l’Abîme…).", "Récompenses de saison : coffres cosmétiques (Commun, Rare, Épique, Légendaire) et lots d’artisanat. Survolez un coffre ou un lot pour voir son contenu exact et ses chances."]], ["Cosmétiques", ["34 cosmétiques de la Saison 1, gardés à vie, même après la fin de la saison.", "Ornements de carte, séparés du cadre : piques de braise en trois tailles, filigrane royal, couronne d’or, chaînes, cercle runique, givre, ailes de braise.", "Cadres de portrait, séparés du cadre de carte : laurier, runes, flammes, ronces, givre, foudre, ossements, constellation.", "Effets de carte (braises, givre, holographique, fumée), traînées quand on déplace une carte (cendres, étincelles, ruban d’ombre, pétales) et trois nouveaux arrière-plans.", "Auras de combat autour de votre héros en aventure, en duel et en défi : cendre, givre, ombre, lumière sacrée, tempête, soif de sang. Votre adversaire la voit en duel."]], ["Personnalisation", ["Nouvelle page : une catégorie par type à gauche, l’aperçu de la carte au centre, la collection à droite avec les filtres Tous, Obtenus et Verrouillés."]], ["Trophées", ["Nouvelle catégorie Saison : 6 trophées à obtenir pendant la saison. Ils restent dans votre collection ensuite et leurs points comptent dans vos points de trophées."]]]},
 {"v": "0.7.5", "t": "Forge : objets du coffre", "sec": [["Forge", ["Les objets d’amélioration rangés dans le coffre apparaissent maintenant à droite de la Forge et de l’Autel d’enchantement, à côté de ceux de l’inventaire : plus besoin de les déplacer dans l’inventaire avant de les utiliser.", "Une petite icône de coffre indique les objets qui se trouvent dans le coffre ; un clic les place directement dans la bonne case."]]]},
 {"v": "0.7.4", "t": "Parchemin : grandes mises à jour seulement", "sec": [["Interface", ["Le parchemin des nouveautés ne présente que les grandes mises à jour. Si vous le masquez, il ne revient qu’à la prochaine grande mise à jour (les petites mises à jour ne le font plus réapparaître)."]]]},
 {"v": "0.7.3", "t": "Parchemin des nouveautés", "sec": [["Interface", ["Le parchemin des nouveautés s’affiche maintenant à chaque arrivée en jeu, juste après avoir choisi votre personnage.", "Une case « Ne plus afficher jusqu’à la prochaine mise à jour » permet de le masquer ; il revient automatiquement à la mise à jour suivante."]]]},
 {"v": "0.7.2", "t": "Spécialisation foudre renommée", "sec": [["Classes", ["La spécialisation foudre du Sorcier s’appelle maintenant Évocateur (avant : Fulguromancie). Rien ne change dans ses talents."]]]},
 {"v": "0.7.1", "t": "Guerrier : léger ajustement", "sec": [["Équilibrage", ["Guerrier un peu moins résistant et un peu moins fort. Au niveau 50 sans équipement : PV 2 211 → 2 064, Force 141 → 136, Défense 98 → 88."]]]},
 {"v": "0.7.0", "t": "L’Hôtel des ventes et la refonte des classes", "sec": [["Classes", ["Refonte complète du Sorcier et du Guerrier : nouvelles compétences de base, nouvelles spécialisations et nouveaux arbres de talents. Vos points de compétence et votre spécialisation sont remboursés.", "Sorcier : Pyromancie (Destruction, Incendie, Cataclysme) avec les degrés de chaleur, et Évocateur (Électrocution, Instabilité, Paralysie) avec les Charges statiques.", "Guerrier : Berserk (Barbare, Commandant, Bourreau) avec la Rage, et Défenseur (Brise-défense, Garde, Stratège) avec la Garde.", "Les arbres sont rangés par niveau (10 à 33). Au niveau 30, choisissez 1 ultime parmi 3. Les deux arbres restent visibles une fois la spécialisation choisie, chacun avec son propre fond.", "Des pointillés relient chaque talent au sort qu’il modifie.", "Barre de sorts : 5 → 7 emplacements ; raccourcis 1 à 8 (touche 1 : attaque de base).", "Les anciens talents communs (Érudition, Vitalité…) sont retirés.", "Nouveaux effets de combat : incantation, sorts à retardement, Brûlures cumulables (jusqu’à 5), ralentissement, réduction de Défense, contre-attaque et marque."]], ["Hôtel des ventes", ["Nouvel onglet Hôtel des ventes dans Communauté : vendez et achetez de l’équipement entre joueurs.", "Acheter : filtres par catégorie, rareté, niveau d’objet et classe, recherche par nom d’objet ou de vendeur, tri par prix, fin de la vente, niveau ou rareté. L’objet acheté arrive dans la messagerie avec le récapitulatif de la commande.", "Vendre : choisissez un équipement du sac, votre prix et la durée de la vente (2 h, 12 h, 24 h, 3 jours ou 7 jours). Taxe de 5 % prise à la vente ; frais de dépôt de 1 % (minimum 10 or) rendus si l’objet est vendu. L’or de la vente arrive dans la messagerie avec un récapitulatif.", "Un objet invendu à la fin de la durée vous est renvoyé par la messagerie avec un récapitulatif. Vous pouvez aussi retirer une vente depuis « Mes ventes ». Maximum 10 objets en vente en même temps.", "Potions et gemmes : bientôt disponibles à l’hôtel des ventes."]], ["Combat", ["Le bouton Combattre n’a plus de flèche. Un engrenage à côté regroupe le combat automatique et Rejouer (qui active aussi le combat automatique).", "Nouveau tri du butin dans l’engrenage : choisissez les raretés d’équipement à garder, et si vous ne gardez que l’équipement de votre classe ou les objets meilleurs que le vôtre. Le reste est recyclé automatiquement à la fin du combat (25 % des ressources rendues), et apparaît barré dans le butin."]], ["Forge", ["Correction : le recyclage n’affiche plus de fer ni de cuir (ces matériaux n’existent plus) ; il rend des Poudres runiques."]], ["Messagerie", ["Les messages peuvent maintenant contenir des objets d’équipement : ils vont dans le coffre du compte quand vous les récupérez."]], ["Interface", ["À la première connexion après une grande mise à jour, un parchemin présente les nouveautés juste après avoir choisi votre personnage."]]]},
 {"v": "0.5.8", "t": "Recyclage manuel", "sec": [["Forge", ["Nouveau « Recyclage manuel » dans l’onglet Recyclage : la souris devient une enclume et chaque objet d’équipement cliqué dans le sac est recyclé (25 % de ses ressources rendues). Recliquez sur le bouton, faites un clic droit ou appuyez sur Échap pour arrêter."]], ["Interface", ["Le menu du navigateur (Inspecter, Code source…) ne s’ouvre plus au clic droit dans le jeu, sauf dans les champs de texte."]]]},
 {"v": "0.5.7", "t": "Équipement mythique portable au niveau 50", "sec": [["Équipement", ["Les objets du mode Mythique (niveau d’objet 60) demandent maintenant le niveau 50 au lieu du niveau 60, qui n’existe pas. Leur niveau d’objet reste 60, avec les mêmes statistiques. Les objets déjà obtenus sont aussi concernés."]]]},
 {"v": "0.5.6", "t": "Grand rééquilibrage des combats", "sec": [["Équilibrage", ["Objectif : des combats plus longs, où les potions et un équipement optimisé font la différence. Au niveau 50, les plus gros coups tournent autour de 4 000 à 6 000 dégâts.", "PV des personnages : environ ×3. Guerrier niveau 50 sans équipement : 757 → 2 211 PV. Sorcier niveau 50 : 737 → 2 161 PV.", "Affixe PV sur l’équipement : environ ×3. Objet niveau 50 : jusqu’à 138 → 414 PV. Les objets que vous possédez déjà sont mis à jour automatiquement.", "Amélioration des objets : +5 % → +3 % par niveau (objet +10 : +50 % → +30 %).", "Monstres : PV ×2, attaque ×1,8. Un monstre niveau 50 : 4 550 → 9 100 PV, attaque 285 → 513. Un combat normal dure maintenant 4 à 6 tours au lieu de 2 à 3.", "Boss normaux : PV ×2, attaque un peu plus faible (−13 %). Un boss dure 10 à 13 tours : une potion de vie peut vous sauver.", "Héroïque : attaque des monstres ×2,6 → ×1,5, PV ×1,6 → ×1,4 ; boss : PV ×1,6 → ×2,8, attaque ×2,9 → ×1,6 ; rage du boss au tour 11 → 16. Les boss héroïques demandent des potions avec un équipement Épique.", "Mythique : attaque des monstres ×2,9 → ×1,8, PV ×2,2 → ×1,8 ; boss : PV ×1,7 → ×3, attaque ×2,2 → ×1,45 ; rage au tour 9 → 13. Il faut un équipement Légendaire ou Divin optimisé et des potions.", "Défis : PV des boss ×6, attaque ×1,4 ; rage au tour 16 → 26. Un défi dure maintenant 15 à 30 tours.", "Duels : chaque joueur commence avec 2,5 × ses PV. Un duel dure maintenant 10 à 20 tours au lieu de 1 à 2."]]]},
 {"v": "0.5.5", "t": "Armures : stats fixes retirées", "sec": [["Équilibrage", ["Casques, armures, jambières et bottes n’ont plus les 3 stats fixes (PV, Défense physique, Résistance magique) en plus de leurs affixes. Exemple : Robe du Titan niveau 13 : +85 PV, +23 Défense physique, +3,8 % Résistance magique → aucune ; il reste ses 2 affixes principales et ses affixes secondaires. Les objets déjà obtenus sont aussi concernés."]]]},
 {"v": "0.5.4", "t": "Cartes flottantes : inclinaison complète", "sec": [["Cartes de joueur", ["Dans les fenêtres de carte (amis et classement), les boutons sur le côté et la croix de fermeture s’inclinent maintenant avec la carte au lieu de rester immobiles, et la carte ne se remet plus à plat quand la souris passe sur ces boutons."]]]},
 {"v": "0.5.3", "t": "Rangement rapide de l’artisanat", "sec": [["Inventaire", ["Nouveau bouton « Tout déposer au coffre » à droite du bouton Coffre : range d’un clic tous les objets d’artisanat de l’inventaire dans l’onglet ouvert du coffre, en complétant les piles existantes."]], ["Coffre", ["Nouveau bouton « Tout récupérer dans l’inventaire » dans l’en-tête du coffre : reprend d’un clic tous les objets d’artisanat de l’onglet ouvert."]]]},
 {"v": "0.5.2", "t": "Combats en arrière-plan et cartes de joueur", "sec": [["Combat", ["Les combats continuent normalement quand vous changez d’onglet ou de fenêtre : le jeu ne ralentit plus en arrière-plan."]], ["Classement", ["La carte d’un joueur du classement s’ouvre maintenant en fenêtre déplaçable, comme celle des amis, avec deux boutons : Inspecter l’équipement et Envoyer une demande d’ami."]], ["Cartes de joueur", ["Les cartes réagissent à la souris : elles s’inclinent du côté où se trouve le curseur, comme s’il appuyait dessus, et suivent ses mouvements."]], ["Équilibrage", ["Points de compétence : 50 au maximum → 35 au maximum (un point par niveau jusqu’au niveau 35). Les personnages qui avaient dépensé plus de 35 points voient leurs compétences réinitialisées, points remboursés."]]]},
 {"v": "0.5.1", "t": "Pause en combat automatique", "sec": [["Combat", ["Nouveau bouton Pause à côté des boutons Auto et Vitesse pendant les combats automatiques : le combat s’arrête après l’action en cours (« En pause » s’affiche sur la scène) et reprend d’un clic. L’enchaînement des combats attend aussi la reprise."]], ["Inventaire", ["Correction : pendant les combats automatiques, l’infobulle d’un objet de l’inventaire disparaissait aussitôt ; elle reste maintenant affichée tant que la souris est sur l’objet."]]]},
 {"v": "0.5.0", "t": "Classement de saison et quêtes", "sec": [["Classement de saison", ["Nouvel onglet Classement dans Communauté, avec deux classements de saison : Duels et Défis. Chaque joueur y apparaît avec sa bannière (icône, cadre, fond et titre).", "Duels : position, victoires, défaites et taux de réussite. Classement par nombre de victoires, puis par taux de réussite.", "Défis : un classement par boss (Colosse de Braise, Wyrm des Glaces, Avatar de l’Abîme) avec le meilleur palier atteint et le nombre de tours. Classement par palier, puis par le moins de tours.", "Décorations selon la position : médailles d’or, d’argent et de bronze pour les 3 premiers, reflet doré sur le 1er, rang doré jusqu’au 10e. Votre propre ligne est entourée de vert.", "Nouveau : cliquez sur un joueur pour sélectionner sa bannière (halo doré), puis inspectez son équipement au moment de son résultat ou affichez sa carte.", "Le classement se met à jour à chaque ouverture. Un classement final est arrêté juste avant la fin de saison : c’est lui qui sert aux récompenses de saison."]], ["Quêtes", ["Nouvelles quêtes journalières : 5 par jour, renouvelées chaque jour à 6 h 00. Récompenses : objets d’artisanat communs et magiques.", "Nouvelles quêtes hebdomadaires : 3 par semaine, renouvelées le mercredi à 6 h 00. Récompenses : objets d’artisanat jusqu’à la rareté épique.", "Quêtes variées : vaincre des ennemis ou un boss, combattre ou gagner un défi, terminer des paliers, défier et battre des joueurs, récolter à la Mine, renforcer un objet, créer des parchemins, ajouter des affixes, faire monter la rareté, recycler, boire une potion de bonus… Seules les quêtes que vous pouvez faire sont proposées.", "Nouveau : Coffre du jour. Récupérez les 5 quêtes du jour pour l’ouvrir : 3 objets d’artisanat garantis, 35 % de chances d’un 4e et 12 % d’un 5e (rareté : Commun 70 %, Magique 25 %, Rare 5 %).", "Ouverture animée du coffre, avec un récapitulatif des objets obtenus. L’animation peut être passée avec le bouton en bas à droite ou la barre Espace.", "Une pastille sur le bouton Quêtes signale une récompense à récupérer."]], ["Amis", ["Nouveau bouton Inspecter sur la carte d’un ami : affiche son équipement et ses statistiques actuels."]]]},
 {"v": "0.4.22", "t": "Même interface sur tous les écrans", "sec": [["Interface", ["L’interface s’adapte maintenant à la taille de l’écran : tout est affiché à la même échelle et avec la même disposition sur tous les ordinateurs, quitte à être un peu plus petit sur les petits écrans. L’inventaire tient entièrement sans avoir à faire défiler.", "Fiche de zone : le texte sur la rage et les techniques des boss (modes Héroïque et Mythique) est retiré ; il décalait et coupait le reste de la fiche."]]]},
 {"v": "0.4.21", "t": "Défis et menus", "sec": [["Aventure", ["Les onglets Aventure, Duel et Défis (anciennement Raid) sont regroupés dans une barre plus lisible : boutons de même taille, bien alignés, avec l’onglet actif en rouge.", "Les boutons de difficulté sont déplacés en haut à gauche de la carte du monde."]], ["Inventaire", ["Le coffre ne s’ouvre plus automatiquement avec l’inventaire : utilisez le bouton Coffre à droite de « Trier »."]], ["Interface", ["Le bouton Aide en bas à gauche est retiré : l’Aide se trouve maintenant dans le menu, avec Options et Changer de personnage.", "Sélection de personnage : un double-clic sur un personnage le lance, comme le bouton Jouer."]]]},
 {"v": "0.4.20", "t": "Nouvel équipement et nouvelles icônes", "sec": [["Inventaire", ["Nouvelle disposition de l’équipement : le personnage en pied au centre, avec son nom, sa classe et son niveau, sur le décor de la zone en cours ; à gauche tête, torse, jambes et pieds ; à droite amulette, anneaux et arme.", "Les statistiques sont toujours affichées à gauche de l’équipement (le bouton Stats est retiré).", "Les boutons Sac de combat et Coffre deviennent des boutons icônes, à droite de la ligne « Trier ».", "Les cases d’équipement ont un fond à la couleur de la rareté de l’objet."]], ["Objets", ["Nouvelles icônes d’équipement : silhouette à la couleur de la rareté, avec un reflet (sac, coffre, équipement, butin et ateliers).", "Les objets de récolte sont retirés du jeu : Lingot de fer, Peau tannée, Herbe enchantée, Éclat de cristal et Fiole d’essence. Ceux que vous possédiez disparaissent du sac et du coffre ; ils ne sont plus demandés dans aucun coût. L’or est conservé."]], ["Aventure", ["Les boutons de difficulté (Normal, Héroïque, Mythique) sont placés en haut à droite de la carte du monde."]], ["Interface", ["Nouvelles barres de défilement aux couleurs du jeu (bronze et doré)."]]]},
 {"v": "0.4.19", "t": "Carte d’ami déplaçable", "sec": [["Amis", ["Un clic sur le nom d’un ami affiche directement sa carte de joueur (le petit menu est retiré).", "La carte reste par-dessus le jeu sans le bloquer et peut être déplacée en la faisant glisser.", "Nouveaux boutons icônes Duel, Chat et Raid, à la verticale sur le bord gauche de la carte ; ils suivent la carte quand on la déplace. Duel et Raid sont grisés si l’ami n’est pas en ligne.", "Petite croix en haut à droite de la carte pour la fermer (ou touche Échap)."]], ["Messagerie", ["Les messages de l’équipe peuvent maintenant s’adresser à vous par votre nom."]]]},
 {"v": "0.4.18", "t": "Icônes de bonus alignées", "sec": [["Interface", ["Les icônes des potions de bonus sont alignées avec le bouton de la messagerie ; le temps restant est affiché juste sous l’icône."]]]},
 {"v": "0.4.17", "t": "Potions de bonus de 30 minutes", "sec": [["Potions", ["Élixir de savoir et Philtre de fortune : l’effet dure maintenant 30 minutes en temps réel (avant : un seul combat). Le temps s’écoule même hors ligne ; une fois les 30 minutes passées, l’effet disparaît.", "Effets inchangés : +50 % d’expérience (Élixir de savoir), +50 % d’or et de matériaux (Philtre de fortune), sur chaque combat gagné pendant la durée.", "Nouveau : ces potions se boivent aussi hors combat, depuis l’inventaire : bouton « Boire » dans le détail de la potion, ou clic droit quand le coffre est fermé. On ne peut pas en boire une deuxième tant que l’effet est actif."]], ["Interface", ["Nouvelle icône de bonus à droite du bouton de la messagerie, à la couleur de la potion (vert pour le savoir, or pour la fortune), avec le temps restant en dessous et une infobulle."]]]},
 {"v": "0.4.16", "t": "Cadenas sur les objets", "sec": [["Objets", ["Un cadenas s’affiche au milieu de l’icône des objets dont le niveau requis n’est pas atteint ; l’icône est assombrie et le niveau de l’objet reste en rouge.", "La bordure de ces objets garde maintenant la couleur de leur rareté (elle était rouge et pouvait faire croire à une autre rareté)."]]]},
 {"v": "0.4.15", "t": "Affixe bonus épique", "sec": [["Objets", ["Nouveau : les objets épiques peuvent aussi arriver avec une affixe bonus (12 % de chances, comme les objets rares). Elle ne compte pas dans les 3 emplacements d’affixes secondaires.", "Bordure rouge plus fine sur les objets dont le niveau requis n’est pas atteint."]]]},
 {"v": "0.4.14", "t": "Nouvelles options", "sec": [["Options", ["Nouvelle page Options en onglets : Raccourcis, Interface, Sauvegarde et Compte.", "Nouveau : les 6 raccourcis de combat se changent dans l’onglet Raccourcis. Cliquez sur une touche puis appuyez sur la nouvelle ; Échap pour annuler. Une touche déjà utilisée est échangée entre les deux raccourcis.", "Bouton « Touches par défaut » pour revenir aux touches 1 à 6. La touche I reste réservée à l’inventaire.", "L’affichage des explications des ateliers se règle aussi dans l’onglet Interface.", "Exporter, importer, connexion et remise à zéro sont rangés dans les onglets Sauvegarde et Compte."]]]},
 {"v": "0.4.13", "t": "Combat plus lisible", "sec": [["Combat", ["Les boutons Combat automatique, Vitesse et Abandon sont déplacés en bas à droite de la scène et légèrement réduits pour ne plus cacher les ennemis.", "Vitesse maximale du combat : ×4 → ×3 (choix : ×1, ×2, ×3).", "Raccourcis : 5 → 6 touches. La touche 1 lance l’attaque de base, les touches 2 à 6 les sorts de la barre.", "Le cadre du raccourci sous chaque sort est plus petit pour mieux voir l’icône.", "Les altérations d’état, bonus et malus s’affichent en icônes sous la barre de PA, avec le nombre de tours restants et une infobulle."]], ["Interface", ["Tous les boutons en icône ont maintenant une infobulle courte (par exemple : « Abandonne le combat »)."]]]},
 {"v": "0.4.12", "t": "Icônes d’objets, tri et raccourcis", "sec": [["Objets", ["Les icônes d’équipement affichent le niveau de l’objet en bas, dans le sac, le coffre et la roue d’équipement.", "Une icône devient rouge quand votre niveau est trop bas pour porter l’objet.", "Nouveaux effets discrets selon la rareté : lueur douce (Rare), reflet qui passe (Épique), petites braises (Légendaire), scintillement (Divin).", "Les objets obtenus n’ont plus que leurs 2 affixes principales. Vous pouvez ajouter jusqu’à 3 affixes secondaires avec des parchemins (avant : 5 affixes au total, principales comprises).", "Les affixes principales et les statistiques fixes ne comptent plus dans le compteur : un objet neuf affiche 0 / 3.", "Nouveau : un objet rare a 12 % de chances d’arriver avec une affixe bonus ; elle ne compte pas dans les 3 emplacements."]], ["Inventaire et coffre", ["Nouveau tri par type d’objet : armes, casques, armures, jambières, bottes, anneaux, amulettes, puis potions, objets d’amélioration et composants.", "Les tris sont regroupés dans un seul bouton (flèches haut et bas) : Type, Nom ou Quantité. Recliquez sur le même tri pour inverser l’ordre.", "Le coffre a maintenant son propre bouton de tri."]], ["Combat", ["Le butin d’équipement s’affiche en icônes ; survolez-les pour voir l’objet (au lieu des fenêtres de détails).", "Nouveau : raccourcis clavier 1 à 5 pour les compétences de la barre de sorts (touches au-dessus de AZERT). Le chiffre est affiché en bas de chaque icône.", "L’inventaire reste ouvert quand un nouveau combat commence.", "Le sac de combat s’ouvre à côté de son bouton, qui reste visible : un deuxième clic le referme."]], ["Aventure", ["Butin de la zone plus lisible : icônes plus grandes et chances affichées en dessous.", "Les ennemis affichés correspondent à l’étape choisie : plus d’icône de boss avant l’étape 10, avec le nombre d’ennemis par combat."]], ["Ateliers", ["Clic droit sur un objet posé dans une case de l’atelier : il est retiré et revient dans le sac."]], ["Interface", ["Il n’y a plus de pastille au passage de niveau : la pastille de la messagerie n’apparaît que pour un message nouveau ou non lu.", "Bouton Amis : un premier clic ouvre la liste, un deuxième la referme."]]]},
 {"v": "0.4.11", "t": "Notes d’équilibrage plus claires", "sec": [["Nouveautés", ["Les notes d’équilibrage des versions précédentes sont réécrites avec des exemples concrets (valeurs d’un ennemi de niveau 10, 30 et 50, exemples de prix) au lieu de formules."]]]},
 {"v": "0.4.10", "t": "Notes à chaque version", "sec": [["Nouveautés", ["Chaque version a maintenant sa propre note de mise à jour : les versions 0.4.1 à 0.4.9 sont ajoutées au journal.", "Une version qui change le deuxième chiffre (0.x.0) est une grande mise à jour ; une version qui change le dernier chiffre (0.0.x) est une mise à jour mineure."]]]},
 {"v": "0.4.9", "t": "Nouveau journal des mises à jour", "sec": [["Nouveautés", ["Nouvelle page Nouveautés en frise chronologique : les grandes mises à jour sont de grandes cartes, les mises à jour mineures des lignes compactes qui se déplient au clic.", "Dans une grande mise à jour, chaque section montre 3 changements ; le bouton « + X autres » affiche la suite et « Réduire » la replie.", "Nouvelles étiquettes sur chaque changement : Nouveau, Amélioré, Équilibrage, Correction.", "Les valeurs modifiées sont mises en évidence : ancienne valeur barrée, nouvelle valeur en vert.", "La version actuelle porte l’étiquette « Actuelle »."]]]},
 {"v": "0.4.8", "t": "Page Personnage et nouvel inventaire", "sec": [["Personnage", ["Nouvelle page Personnage : bandeau avec le portrait, le niveau, la barre d’expérience et les statistiques principales (PV, statistique de classe, Défense, Défense magique, Vitesse, Critique, Puissance).", "Les points de compétence à dépenser sont affichés dans un badge violet, à côté des boutons « Détail des statistiques » et « Ascension ».", "Deux onglets : Compétences (compétences de base et spécialisation à gauche, détail de la compétence et barre de sorts à droite) et Statistiques détaillées (Attaque, Défense, Résistances, base + équipement, Ascension).", "La roue d’équipement n’est plus sur cette page : elle se trouve dans l’inventaire."]], ["Inventaire", ["La roue d’équipement est maintenant dans l’inventaire, en haut à droite, avec le sac en dessous.", "Nouveau bouton « Stats » : affiche les statistiques du personnage à gauche de la roue ; un deuxième clic les masque.", "L’inventaire s’ouvre en bas à droite et le coffre du compte en bas à gauche ; sur ordinateur, le coffre s’ouvre en même temps que l’inventaire.", "Glisser-déposer, clic droit pour équiper, tri et sac de combat fonctionnent comme avant."]], ["Interface", ["La signature sous le titre est retirée : seule la version du jeu reste affichée."]]]},
 {"v": "0.4.7", "t": "Aventure compacte et combat", "sec": [["Interface", ["Titre de saison plus grand, vert et lumineux.", "Barre du bas resserrée ; le médaillon et le texte Aventure sont abaissés pour s’aligner avec les autres boutons.", "Pastille violette sur le portrait quand des points de compétence ne sont pas dépensés."]], ["Messagerie et carte de joueur", ["La pastille de la messagerie ne revient plus après avoir tout lu et tout récupéré : l’état des messages, les trophées, le coffre et les cosmétiques sont maintenant sauvegardés en ligne.", "Boutons « Écrire » et « Envoyer un message » réalignés avec leur icône.", "La carte de joueur est mise à jour après une remise à zéro : les anciens trophées n’apparaissent plus."]], ["Équipement", ["Les affixes principales sont affichées en premier, dans l’ordre PV puis statistique de classe."]], ["Aventure", ["Fiche de zone compacte : tout tient sans défiler, ennemis et boss sur une seule ligne.", "Les cases « Combat automatique » et « Enchaîner les combats » sont remplacées par des boutons icônes à côté de Combattre."]], ["Combat", ["L’inventaire peut être ouvert pendant un combat ; l’équipement ne peut être changé qu’entre les combats.", "Abandonner (2 clics) ramène au choix d’aventure.", "Les boutons Auto, Vitesse et Abandon sont placés sous l’ordre du tour (Abandon aussi en duel et en raid)."]], ["Collecte", ["Seule la Mine reste active et ne produit plus que de l’or : 15 or par récolte (inchangé), fer par récolte 4 → 0.", "Arbre de la Mine : Cadence, Veine d’or et Entrepôt (valeurs inchangées).", "Forêt Enchantée, Ruines englouties et Marais des brumes : « Arrive dans une prochaine mise à jour »."]]]},
 {"v": "0.4.6", "t": "Raids en solo et titre de saison", "sec": [["Raids", ["Nouveau : les raids peuvent se faire seul avec le bouton « Combattre seul ». En solo, le boss a 65 % de PV en moins et 35 % d’attaque en moins ; les récompenses sont réduites de 40 %.", "Raids à deux légèrement plus faciles. Exemple, Colosse au palier +0 : PV 8 170 → 8 050, Force 197 → 189."]], ["Interface", ["Le titre de la saison s’affiche sous « Cendrelame ».", "Bouton d’aide placé à gauche du titre.", "Dans les ateliers, les objets de l’inventaire qui ne peuvent pas être utilisés sont grisés au lieu d’être masqués.", "Cercle runique et emplacements de composants recentrés.", "Icône du Marchand recentrée en haut à droite."]]]},
 {"v": "0.4.5", "t": "Équilibrage des ennemis et confort", "sec": [["Équilibrage", ["PV des ennemis en hausse, surtout en début de partie. Ennemi niveau 10 : 440 → 950 PV ; niveau 30 : 1 440 → 2 750 PV ; niveau 50 : 2 680 → 4 550 PV.", "Attaque des ennemis plus régulière : plus forte en début de partie, un peu plus faible à haut niveau. Niveau 10 : 43 → 65 ; niveau 30 : 157 → 175 ; niveau 50 : 327 → 285.", "Défense des ennemis légèrement en hausse. Niveau 10 : 16 → 22 ; niveau 30 : 48 → 58 ; niveau 50 : 88 → 94.", "Les boss sont adoucis par rapport aux ennemis normaux : 40 % de PV en moins et 25 % d’attaque en moins.", "Barrière arcanique : le bouclier valait 220 % de votre Intelligence et se montait sur 5 rangs ; il vaut maintenant 30 % de vos PV maximum, en 1 seul rang. Exemple avec 1 000 PV : bouclier de 300 PV."]], ["Équipement", ["Niveau requis sur les objets : égal au niveau des ennemis qui l’ont lâché.", "Cliquer sur un emplacement d’équipement ouvre l’inventaire filtré sur ce type d’objet."]], ["Forge et inventaire", ["Le bouton « Créer » de la Forge est retiré.", "Les boutons de destruction de l’inventaire sont retirés.", "L’inventaire reste opaque quand on le déplace."]], ["Interface", ["Les notifications s’affichent en bas à gauche.", "La position de défilement est conservée quand on clique sur un bouton.", "Vitrine du Marchand : icônes centrées."]]]},
 {"v": "0.4.4", "t": "Nouvelle saison", "sec": [["Saisons", ["Nouvelle fenêtre « Nouvelle saison » affichée au début d’une saison, avec son titre et son message."]]]},
 {"v": "0.4.3", "t": "Refonte de l’amélioration", "sec": [["Objets", ["Les objets ont 2 affixes principales, plus jusqu’à 3 affixes ajoutées avec des parchemins.", "Écart de puissance entre raretés réduit. Bonus de statistiques par rapport à un objet commun : Magique 5 % (inchangé) ; Rare 12 % → 10 % ; Épique 22 % → 15 % ; Légendaire 35 % → 20 % ; Divin 50 % → 25 %.", "Nouvelles pierres de rareté pour faire monter un objet de rareté."]], ["Forge et Enchantement", ["Nouvel atelier Enchantement.", "Pierre de renforcement : chance de réussite 100 % → 10 %.", "La Forge coûte 4 fois moins cher (−75 %)."]], ["Composants et collecte", ["Les composants sont rangés dans l’inventaire ; il en faut 4 fois moins (−75 %).", "Quantité gagnée par récolte : fer 15 → 4, plante 9 → 2, cuir 9 → 2, cristal 15 → 4, essence 6 → 2. Stock maximum de cristal 100 → 25.", "Les ennemis lâchent 4 fois moins de composants (−75 %) ; chaque zone a maintenant son propre butin."]], ["Économie", ["Prix du Marchand multipliés par 3. Exemple : Potion d’oubli 5 000 → 15 000 or.", "Or gagné en combat réduit de 30 % (exemple : 100 → 70 or)."]]]},
 {"v": "0.4.2", "t": "Nouveaux décors", "sec": [["Décors", ["Nouveaux décors détaillés pour toutes les zones d’aventure, l’arène de duel et le glacier du Wyrm."]]]},
 {"v": "0.4.1", "t": "Combat avec sprites", "sec": [["Combat", ["Nouvelle fenêtre de combat : les héros et les ennemis sont affichés en sprites, jusqu’à 3 contre 3.", "L’ordre du tour est affiché en haut, avec un bouton rond « Fin du tour » au centre.", "Boutons en icônes, chacun avec une infobulle."]], ["Sac de combat", ["Nouveau sac de combat : choisissez les potions emportées, en quantité limitée par combat.", "Limites : potion de vie 10, résistance 3, force 3, intelligence 3, action 2, Élixir 1, Philtre 1."]]]},
 {v:'0.4.0',t:"Trophées, communauté et nouveaux héros",sec:[
  ["Personnages", ["Nouvel écran de sélection : les cinq emplacements en grandes cartes verticales, chaque héros en pied avec sa classe, son niveau et les boutons Jouer et Supprimer ; le personnage actuel est mis en évidence.", "Nouvel écran de création en forme de registre : nom, classe, apparence, statistiques de départ et aperçu des spécialisations de la classe (description, compétences et talent ultime), avec le héros en grand à droite et le bouton « Créer le personnage ».", "Le Sorcier a deux apparences au choix lors de la création. Le Guerrier garde son portrait en attendant ses illustrations."]],
  ["Coffre des Reliques", ["Nouveau butin de raid : le Coffre des Reliques. Chaque raid réussi a une chance d’en donner un : 1 % au palier +0, +0,5 % par palier, jusqu’à 10 % (palier +18 et au-delà). Il arrive dans le sac (ou dans le coffre du compte si le sac est plein).", "Infobulle du coffre : description et chance d’obtention, sans révéler son contenu.", "Clic droit sur le coffre dans le sac : une fenêtre demande confirmation, puis un tirage animé fait défiler les reliques avant de s’arrêter sur la récompense.", "Chances par relique : Or royal 38 % (commun), Saphir 27 % (peu commun), Améthyste 20 % (rare), Braise vivante 11 % (épique), Prisme holographique 4 % (légendaire).", "Relique déjà possédée : convertie en or (2 000, 3 000, 5 000, 8 000 ou 15 000 selon la rareté).", "Les administrateurs peuvent aussi joindre des Coffres des Reliques aux messages système.","Le coffre apparaît dans la liste des récompenses de chaque boss de raid, avec sa chance au palier choisi et une infobulle."]],
  ["Messagerie", ["Nouvelle messagerie du compte : bouton rond avec une enveloppe à droite du portrait (en haut à gauche), avec le nombre de messages non lus.", "Les messages système de l’équipe (informations, alertes de maintenance, cadeaux et compensations) arrivent en direct, avec une notification. Ils peuvent être envoyés à tous les joueurs ou à un seul.", "Fenêtre en deux colonnes : la liste des messages (non lus en gras, icône cadeau s’il reste des pièces jointes) et le message ouvert.", "Pièces jointes : bouton « Récupérer » ou « Tout récupérer ». L’or s’ajoute à votre or ; les matériaux et potions vont dans le coffre du compte (tous onglets). S’il n’y a pas assez de place dans le coffre, un message l’indique et rien n’est récupéré.", "Chaque pièce jointe ne peut être récupérée qu’une fois par compte ; elle peut avoir une date d’expiration. Un message peut être supprimé une fois ses pièces jointes récupérées."]],
  ["Trophées", ["Nouveau bouton « Trophées » dans la barre du bas, avec un point rouge quand un trophée vient d’être obtenu.", "30 trophées répartis en 5 catégories : Aventure, Personnage, Amélioration, Collecte, Duel et raid. Chacun rapporte des points de trophées : 5 à 15 points (bronze), 15 à 49 points (argent), 50 points et plus (or), jusqu’à 100 points pour vaincre Le Dévoreur en difficulté Mythique.", "Page Trophées : à gauche le total de points, la progression et les catégories avec leur compteur ; à droite les 3 derniers trophées obtenus, puis la liste filtrable (Tous, Obtenus, À obtenir) avec la barre d’avancement et la date d’obtention.", "Les trophées sont liés au compte (tous les personnages y contribuent). Ceux déjà mérités avant cette version (niveaux, boss vaincus, zones ouvertes, raids, duels…) sont attribués automatiquement à la connexion.", "Une notification s’affiche à chaque trophée obtenu.", "Certains trophées débloquent un titre à afficher sur votre carte de joueur."]],
  ["Communauté", ["La page Communauté a quatre onglets : Carte de joueur, Personnalisation, Classement et Guilde (ces deux derniers arrivent dans une prochaine mise à jour).", "Carte de joueur : votre carte (icône, nom, titre, points de trophées, 3 trophées mis en avant, personnages et leur niveau) et l’aperçu de la bannière qui servira au classement.", "Personnalisation : icône (portraits de classe ou emblèmes), cadre (Or et Argent, puis Azur à 50 points, Améthyste à 150, Émeraude à 300, Braise à 500), fond (débloqué en battant le boss de chaque zone, en réussissant un raid ou en gagnant un duel), titre et 3 trophées affichés. Aperçu en direct."]],
  ["Amis", ["La liste d’amis n’est plus dans Communauté : un bouton rond à côté du sac l’ouvre, avec le nombre d’amis connectés en vert et un point rouge pour les demandes et messages non lus.", "En cliquant sur le nom d’un ami, le nouveau bouton « Carte » affiche sa carte de joueur."]],
  ["Interface",["Quand une nouvelle version du jeu est mise en ligne pendant que vous jouez, un bandeau rouge apparaît en haut de la page (vérification toutes les 2 minutes et au retour sur l’onglet). Il reste affiché jusqu’au rafraîchissement de la page ; le bouton « Rafraîchir maintenant » sauvegarde puis recharge le jeu.","Barre du bas : Marchand, Amélioration, Collecte, Aventure (au centre), Communauté, Trophées et Quêtes (verrouillé, arrive dans une prochaine mise à jour). Les deux côtés ont maintenant trois boutons et le médaillon Aventure est centré.","En-tête plus aéré : plus d’espace au-dessus et au-dessous du titre et du portrait.","Le bouton de messagerie est aligné avec le cadre du personnage.","Les objets du coffre du compte sont comptés dans les quantités possédées (Forge, Marchand, coûts) et peuvent être dépensés directement : le sac est utilisé en premier, puis le coffre."]],
  ["Personnalisation", ["5 nouveaux cadres animés (reliques), appliqués à la carte de joueur, à la bannière du classement et au contour de l’icône : Or royal (reflet balayant), Saphir (halo tournant), Améthyste (étincelles), Braise vivante (lueur pulsante) et Prisme holographique (arc-en-ciel). Ils s’obtiennent uniquement dans le Coffre des Reliques.","Contour de l’icône de la carte et de la bannière un peu plus fin.","Tous les éléments, même verrouillés, peuvent être sélectionnés pour un aperçu complet de la carte et de la bannière. Les changements ne sont enregistrés qu’avec le nouveau bouton « Confirmer » (« Annuler » revient à la carte actuelle) ; si un élément verrouillé est sélectionné, la confirmation est impossible et l’élément est indiqué.","Chaque icône, cadre, fond et trophée affiché a une infobulle : date et raison du déblocage, ou comment le débloquer.","L’onglet Carte de joueur affiche la carte au centre, sans fond, avec la bannière du classement centrée en dessous.","La carte d’un ami s’affiche seule au centre de l’écran ; un clic en dehors la ferme (plus de croix ni de boutons Duel et Chat)."]]
 ]},
 {v:'0.3.2',t:"Coffre du compte et nouvelle interface",sec:[
  ["Nouvelle interface", ["Le menu principal passe en bas de l’écran, avec des boutons illustrés : Marchand, Amélioration, Aventure (grand médaillon central), Collecte et Communauté.", "Le sac est un bouton rond en bas à droite (même effet que la touche I) ; un point rouge signale les nouveaux objets. L’Aide est un bouton rond en bas à gauche.", "Le Personnage s’ouvre en cliquant sur le portrait en haut à gauche (nom, classe, niveau et barre d’expérience).", "Communauté ouvre la liste d’amis et les messages (compte en ligne requis) ; un point rouge signale les demandes et messages non lus.", "Zone de jeu plus large (jusqu’à 1440 pixels au lieu de 1140) et en-tête plus compact pour limiter le défilement.", "Les composants et l’or restent affichés dans la fenêtre d’inventaire."]],
  ["Aventure", ["Nouvelle carte du monde : chaque zone est un médaillon illustré sur un parchemin, reliées par un chemin (plein pour les zones terminées, en pointillés pour la suite).", "Badges sur la carte : coche pour une zone terminée, progression (ex. 4/10) pour la zone en cours, cadenas pour les zones verrouillées.", "Fiche de la zone à droite : difficulté (Normal, Héroïque, Mythique), chemin des 10 étapes avec le boss, ennemis et leur niveau, boss de la zone, bouton Combattre, combat automatique et enchaînement.", "Sélecteur Aventure / Duel / Raid en haut de la page."]],
  ["Duel et raid", ["Nouvelle page Duel : une arène avec votre portrait face à l’adversaire, le bouton « Rechercher un adversaire » au centre et la récompense de victoire (+500 or).", "Fiche Duel à droite : votre bilan (victoires, défaites, pourcentage de réussite avec une barre) et la liste « Défier un ami », avec un bouton Duel pour chaque ami en ligne (amis en ligne en premier).", "Nouvelle page Raid : les trois boss sont des médaillons illustrés sur la carte (lave, glace, néant), avec leur palier maximum et un cadenas si le niveau requis n’est pas atteint.", "Fiche du boss à droite : description, niveau, PV, attaque, défenses, résistances, compétences, choix du palier par boutons (+0, +1…, le palier suivant est affiché verrouillé), récompenses, « Rechercher un partenaire » et « Inviter un ami » (ouvre la liste d’amis)."]],
  ["Amélioration", ["Le bouton Forge de la barre du bas devient « Amélioration » et ouvre le menu des ateliers.", "Quatre ateliers en haut de la page : Forge, Enchantement, Alchimie et Runomancie. Enchantement, Alchimie et Runomancie sont verrouillés (« Arrive dans une prochaine mise à jour »).", "La Forge a trois onglets : Créer, Renforcer (ancien mode Amélioration) et Recycler.", "Créer : types d’objets en icônes à gauche, enclume au centre (choix de la forge, objet, bouton Forger), chances de rareté, coût et dernière création à droite.", "Renforcer : roue d’équipement à gauche, objet sur l’enclume au centre, et à droite les actions en cartes (Améliorer avec le passage +N → +N+1, Relancer les valeurs, Remplacer une affixe) avec leur coût.", "Recycler : la destruction en masse a sa propre page ; chaque seuil (commun, magique, rare) affiche le nombre d’objets concernés et les ressources récupérées, et demande une confirmation (avant : destruction immédiate).", "Dans les détails d’un objet, le bouton « Forge » devient « Renforcer »."]],
  ["Marchand et collecte", ["Nouveau Marchand en forme d’étal : le marchand et son or en haut, des filtres (Tout, Combat, Progression, Spéciaux) et les potions en vitrine avec leur prix et le nombre possédé.", "Cliquer sur une potion ouvre sa fiche à droite : effet, nombre possédé, recharge, prix, choix de la quantité (− / +, ×1, ×5, ×10, ×25 ou Max), total et bouton Acheter. La raison d’un achat impossible est indiquée (classe, place dans le sac ou ressources).", "Nouvelle page Collecte en tableau : une ligne par zone avec son illustration, son niveau, la production par récolte, la barre de progression, l’arbre d’améliorations, la récolte automatique et le bouton Collecter.", "Panneau de droite : bouton « Tout collecter » (récupère toutes les zones prêtes d’un coup), production par heure de toutes les zones et stock de chaque matériau par rapport au maximum (en rouge quand il est plein)."]],
  ["Coffre", ["Nouveau coffre lié au compte : bouton « Coffre » dans la fenêtre d’inventaire. Chaque onglet fait 15 × 5 cases.", "Les objets et les piles déposés dans le coffre sont récupérables par tous les personnages du même compte (sauvegarde locale et en ligne).", "Glissez-déposez entre l’inventaire et le coffre, ou faites un clic droit sur un objet pour l’envoyer de l’un à l’autre. Les piles d’un même matériau fusionnent (500 max).", "Achat d’onglets supplémentaires (6 au maximum) avec l’or partagé : 2e onglet 5 000 or, 3e 15 000, 4e 40 000, 5e 100 000, 6e 250 000 (double clic pour confirmer).", "Renommez un onglet avec le bouton ✎ ou un double clic sur son nom (16 caractères au maximum)."]],
  ["Équipement", ["La touche Alt gauche affiche les plages possibles des affixes (avant : Maj).", "La touche Maj affiche un comparatif entre l’objet survolé et l’objet équipé au même emplacement : les deux fiches côte à côte et la différence stat par stat (gains en vert, pertes en rouge).", "Pour les anneaux, Ctrl gauche change l’emplacement comparé (Anneau ou Anneau (2))."]],
  ["Inventaire", ["L’or et les composants sont affichés sous les cases de l’inventaire (et ne sont plus en haut de la page). Une infobulle donne la quantité, le stock maximum et l’utilité de chacun.", "Les objets gardent leur taille dans le coffre (par exemple une arme occupe 5 cases en hauteur).", "Cliquer sur la fenêtre d’inventaire ou du coffre la fait passer au premier plan.", "Boutons d’onglet actif et bouton du coffre dans un brun clair assorti aux fenêtres (au lieu du rouge)."]]
]},
 {v:'0.3.1',t:"Raids, spécialisations et équilibrage",sec:[
  ["Compétences et spécialisations",["Nouveau système de compétences pour chaque classe : 3 compétences de base jusqu’au niveau 10, puis une spécialisation à choisir dans la fenêtre Personnage.","Chaque spécialisation a son propre arbre de talents (8 talents de spécialisation, actifs et passifs, reliés par des traits, plus 5 talents communs et 1 talent ultime) : un talent relié se débloque quand le talent précédent est appris et que le niveau requis est atteint (10, 12, 15, 20, 25, 30 et 35 pour l’ultime).","Le choix est définitif. La nouvelle Potion d’oubli (Marchand : 5 000 or et 5 Prismes divins) réinitialise toutes les compétences et la spécialisation, avec remboursement des points.","Compétences affichées sous forme d’icônes ; une infobulle détaille l’effet, le rang actuel, le rang suivant et les conditions. Cliquez sur une icône pour l’apprendre ou l’équiper. Les passifs sont ronds, les actives carrées.","Fiches de compétences plus lisibles : coût en PA, recharge, élément et cible en étiquettes, effets en paragraphes séparés et rang suivant à part.","Barre de sorts : jusqu’à 5 compétences actives (avant 3), à placer par glisser-déposer dans la fenêtre Personnage, et affichées en icônes avec le coût en PA et la recharge restante, dans les combats d’aventure, les duels et les raids.","Talents communs (dans chaque arbre, sans lien) : Guerrier — Puissance brute (+2 % Force, 5 rangs), Précision mortelle (+2 % critique, 3 rangs), Robustesse (+2 % PV, 5 rangs), Célérité (+2 % vitesse, 3 rangs), Peau d’acier (+2 % défense physique et magique, 3 rangs). Sorcier — Érudition (+2 % Intelligence, 5 rangs), Précision mortelle, Vitalité (+2 % PV), Célérité, Égide (mêmes valeurs).","Talent ultime dans chaque arbre (niveau 35, 20 points dépensés dans l’arbre requis) : Flamme intérieure (Feu), Cœur de l’orage (Foudre), Frénésie sanglante (Saignement), Rage indomptable (Barbarie).","Les talents qui modifient un effet ou une statistique ne sont plus reliés : Feu persistant, Plaies profondes, Choc nerveux, Vif-argent et Berserker se prennent librement (niveau requis conservé).","Points : un arbre complet demande 57 points (37 de spécialisation, 19 communs, 1 ultime) en plus des 15 points des compétences de base, alors qu’un héros niveau 50 n’en possède que 51 : il faut faire des choix.","Toutes les sauvegardes existantes : les compétences sont réinitialisées et tous les points de compétence sont remboursés."]],
  ["Personnage",["Nouvelle roue d’équipement : la roue occupe toute la largeur de sa zone, avec en dessous la liste de l’équipement porté (nom, amélioration, niveau d’objet).","Nouvelle disposition : en haut, la présentation du personnage et ses statistiques à gauche, la roue d’équipement à droite, de la même taille ; en dessous, les compétences et talents.","Forge : l’inventaire n’est plus affiché dans l’onglet Forge ; glissez un objet depuis la fenêtre d’inventaire sur l’enclume (bouton « Ouvrir l’inventaire »). Glissez l’objet hors de l’enclume pour l’en retirer.","Inventaire dans une fenêtre que l’on peut déplacer : elle s’ouvre en cliquant sur un emplacement d’équipement ou avec la touche I, depuis n’importe quel onglet (sauf pendant un combat), et se ferme avec la croix, la touche I ou Échap. Boutons de tri et de destruction regroupés en haut, détails de l’objet sélectionné dans la fenêtre.","Nouvelle barre de sorts (5 emplacements) au-dessus des compétences : glissez-déposez une compétence active apprise dans un emplacement, déplacez-la d’un emplacement à l’autre pour changer l’ordre, ou glissez-la hors de la barre pour la retirer. L’ordre de la barre est celui des combats."]],
  ["Guerrier",["Compétences de base : Frappe puissante (niv. 1, 200 % FOR, 2 PA), Mur de boucliers (niv. 3, bouclier de 30 % des PV + provocation), Tourbillon (niv. 6, 130 % FOR sur tous les ennemis).","Spécialisation Saignement : Entaille (150 % FOR, 50 % de chances d’infliger Saignement : 40 % FOR par tour, 3 tours), Lames dentelées (+10 % de chances de Saignement avec Entaille par rang, jusqu’à 100 %), Hémorragie (+10 % de dégâts des Saignements et +1 % de vol de vie par rang), Éventration (160 % FOR, +60 % contre une cible qui saigne), Lacération (100 % FOR sur tous les ennemis, 60 % de chances de Saignement), Odeur du sang (+5 % de dégâts contre les cibles qui saignent et +3 % PV par rang), Plaies profondes (+1 tour de Saignement par rang, 2 rangs), Exsanguination (140 % FOR et détonation : 150 % des dégâts de Saignement restants infligés immédiatement).","Ultimes du Guerrier : Frénésie sanglante — chaque compétence qui touche une cible qui saigne octroie 1 charge de Soif ; à 5 charges, Frénésie : +20 % de dégâts et +6 % de vol de vie pendant 3 tours. Rage indomptable — chaque coup subi octroie 1 point de Rage ; à 5 points, Déchaînement : +20 % de dégâts et −15 % de dégâts subis pendant 3 tours.","Spécialisation Barbarie : Frappe sauvage (160 % FOR, +7 % de dégâts par tranche de 10 % de PV manquants), Fureur (+1,2 % de dégâts par tranche de 10 % de PV manquants par rang), Instinct de survie (−5 % de dégâts subis sous 35 % de PV et +3 % PV par rang), Pacte de sang (sacrifie 10 % des PV max, 210 % FOR, +5 % par tranche de 10 % de PV manquants), Cri de guerre (+25 % de Force pendant 3 tours), Carnage (115 % FOR sur tous les ennemis, +5 % par tranche de 10 % de PV manquants), Berserker (+4 % vitesse, +2 % critique et +1 % vol de vie par rang, 3 rangs), Folie meurtrière (200 % FOR, +8 % par tranche de 10 % de PV manquants, rend 15 % des dégâts en PV)."]],
  ["Sorcier",["Compétences de base : Projectile arcanique (niv. 1, 180 % INT, 2 PA), Barrière arcanique (niv. 3, bouclier de 220 % INT sur les alliés), Nova arcanique (niv. 6, 95 % INT sur tous les ennemis).","Spécialisation Feu : Immolation (150 % INT de feu, 50 % de chances d’infliger Brûlure : 40 % INT par tour, 3 tours), Embrasement (+10 % de chances de Brûlure avec Immolation par rang, jusqu’à 100 %), Chaleur intense (+10 % de dégâts des Brûlures et +3 % INT par rang), Combustion (80 % INT et détonation : 150 % des dégâts de Brûlure restants infligés immédiatement), Vague de flammes (100 % INT sur tous les ennemis, 50 % de chances de Brûlure), Pyromanie (+5 % de dégâts contre les cibles en feu et +1 % critique par rang), Feu persistant (+1 tour de Brûlure par rang, 2 rangs), Météore (220 % INT sur tous les ennemis, 60 % de chances de Brûlure).","Spécialisation Foudre : Arc électrique (180 % INT de foudre, 30 % de chances de paralyser 2 tours), Électricité statique (+7 % de chances de paralyser et +3 % INT par rang), Vif-argent (+4 % vitesse et +2 % critique par rang, 3 rangs), Éclair en chaîne (100 % INT sur tous les ennemis, 15 % de chances de paralyser), Choc nerveux (+10 % de chances qu’une cible paralysée perde son tour par rang, 3 rangs), Surtension (+8 % de dégâts contre les cibles paralysées et +1 % critique par rang), Tempête (140 % INT sur tous les ennemis, 20 % de chances de paralyser), Jugement de foudre (260 % INT, dégâts doublés contre une cible paralysée).","Ultimes du Sorcier : Flamme intérieure — chaque sort de feu lancé octroie 1 degré de Chauffe ; à 5 degrés, Surchauffe : +20 % de dégâts de feu pendant 3 tours. Cœur de l’orage — chaque sort de foudre lancé octroie 1 Charge ; à 5 Charges, Surcharge : +20 % de dégâts de foudre et +15 % de chances de paralyser pendant 3 tours.","Nouvel effet Paralysie (2 tours) : à chaque tour, la cible a 50 % de chances de perdre son tour (jusqu’à 80 % avec Choc nerveux). Les boss n’ont que la moitié des chances d’être paralysés."]],
  ["Raids",["Nouveau mode « ☠ Raid » dans l’onglet Aventure : combat coopératif à 2 joueurs contre un boss unique et très puissant.","Trois boss de raid : Colosse de Braise (niveau 25, niveau 20 requis), Wyrm des Glaces (niveau 40, niveau 35 requis) et Avatar de l’Abîme (niveau 50, niveau 50 requis).","Paliers : chaque victoire débloque le palier suivant (+1) pour ce boss. La difficulté est exponentielle : PV, attaque et défense du boss ×1,05 par palier (palier +10 : ×1,63 ; palier +20 : ×2,65). Le palier se choisit dans un menu déroulant avant le combat ; les deux joueurs doivent l’avoir débloqué.","Recherchez un partenaire (même boss, même palier) ou invitez un ami depuis la liste d’amis (nouveau bouton « Raid » sous « Duel »).","Le boss agit deux fois par tour et entre en rage au tour 16 (+8 % de dégâts par tour). Les héros étourdis passent leur tour automatiquement.","Récompenses (palier +0, multipliées par 1,05 par palier pour l’or) : Colosse 1 150 or, Wyrm 1 600 or, Avatar 1 900 or, plus 2 runes (+1 tous les 3 paliers), 6 essences et 6 cristaux (+1 par palier).","Un joueur inactif pendant 90 secondes peut voir son tour passé par son partenaire. Si un joueur abandonne, son partenaire peut continuer seul."]],
  ["Combat",["Les PA sont désormais entièrement rechargés au début de chaque tour (avant : +1 PA par tour), en aventure, en duel et en raid.","Chaque potion a désormais son propre temps de recharge (vie, résistance, force et intelligence : 4 tours ; action : 6 tours) : plusieurs potions différentes peuvent être bues dans le même tour.","Préparation de 10 secondes avant chaque combat (aventure, duel et raid) pour boire vos potions. En duel et en raid, les deux joueurs se préparent en même temps ; le combat commence dès que les deux sont prêts. Les combats enchaînés automatiquement n’ont pas de préparation.","Toutes les compétences des héros sont utilisables dès le premier tour ; leur recharge commence une fois lancées.","Nouvelle fenêtre de combat « Arène sombre » : scène nocturne, portraits, cartes vitrées et « VS » central, barre de sorts et journal sombres. L’ordre du tour est affiché en haut (l’unité qui joue est mise en avant). Même ambiance pour les duels et les raids.","Bouclier visible sur la barre de vie : une bande bleue translucide montre la part de vie protégée, en plus du montant entre parenthèses (aventure, duel et raid).","Les dégâts et les soins s’affichent sur la cible puis disparaissent lentement en fondu, en aventure comme en duel et en raid.","Infobulles sur les compétences et les potions pendant les combats (aventure, duel et raid) : coût, recharge, cible et effets.","Le bouton « Fuir » devient « Abandonner » (double clic pour confirmer) : l’abandon est compté comme une défaite. Même bouton en duel et en raid.","Chat de combat à droite de la scène, réservé aux deux joueurs du duel ou du raid."]],
  ["Marchand",["Nouvelle Potion d’action (70 or de base) : +2 PA (et +2 PA maximum) pendant 3 tours.","En aventure et en raid : utilisable à n’importe quel tour (et pendant la préparation), 6 tours de recharge.","En duel PvP : utilisable uniquement pendant la préparation ou à votre premier tour (ne coûte pas de PA).","Nouvelle Potion d’oubli : 5 000 or et 5 Prismes divins, réinitialise compétences et spécialisation."]],
  ["Équipement",["Nouvelle stat fixe sur les armures : Résistance magique. Guerrier (niveau 50, Épique) : heaume 4,3 %, cuirasse 6,7 %, jambières 5,1 %, bottes 3,4 %. Sorcier : capuche 6,1 %, robe 8,5 %, jambières 6,7 %, sandales 4,3 %. Les objets existants la reçoivent aussi.","Rareté des affixes : chaque affixe a désormais un poids de tirage. Très courants : PV, Force, Intelligence (16). Courants : Défense, Vitesse (9), résistances élémentaires (7). Peu courants : PV %, Résistance physique, Résistance magique, Or trouvé (5). Rares : Dégâts % (4), Critique, Dégâts critiques, Esquive (3). Très rare : Vol de vie (2).","Exemple pour le premier affixe d’un objet de Guerrier : PV ou Force ≈ 14 % chacun, Critique ≈ 2,7 %, Vol de vie ≈ 1,8 %. Le tableau complet est dans l’Aide (Rareté et équipement). Le remplacement d’affixe à la Forge suit les mêmes chances."]],
  ["Équilibrage : plafonds",["Chances de coup critique plafonnées à 70 % (base 5 %).","Dégâts critiques plafonnés à 200 % (base 150 %) : un critique inflige au maximum le double des dégâts."]],
  ["Équilibrage : affixes",["Valeurs maximales d’un affixe sur un objet Épique de niveau 50 (avant → après) :","PV : 205 → 168 (−18 %) · Force / Intelligence : 57 → 39 (−32 %) · Défense : 48 → 39 (−19 %) · Vitesse : 8,5 → 7,3 (−14 %).","PV % : 9,8 → 8,5 (−13 %) · Dégâts % : 11 → 7,9 (−28 %) · Critique : 6,7 → 5,5 % (−18 %) · Dégâts critiques : 37,8 → 9,8 % (−74 %, à cause du nouveau plafond).","Esquive : 3,9 → 3,4 % (−14 %) · Vol de vie : 2,5 → 2 % (−22 %). Résistances et Or trouvé : inchangés.","Objets existants : chaque affixe garde sa qualité de tirage (sa position entre le minimum et le maximum) dans la nouvelle plage. Les stats fixes des objets sont recalculées."]],
  ["Équilibrage : objets divins",["Les objets Divins n’ont plus de pouvoir passif et n’ont plus que 3 affixes aléatoires, mais toujours au maximum de leur plage (multiplicateur ×1,5 inchangé).","Les objets Divins existants sont convertis : pouvoir retiré, 3 premiers affixes conservés et portés à leur valeur maximale."]],
  ["Équilibrage : classes",["Guerrier : PV +13 par niveau (avant 14) ; Force +2,6 par niveau (avant 2,4).","Sorcier : PV de base 100 (avant 90), +13 par niveau (avant 10,5) ; Défense de base 6 (avant 5), +1,5 par niveau (avant 1).","Équipement du Sorcier plus résistant : Défense fixe des capuches, robes, sandales et jambières augmentée d’environ 20 à 25 %.","Simulations finales (équipement Légendaire +10, boss Mythique, talents communs et ultimes compris) : Saignement ≈ 80 % de victoires, Foudre ≈ 65 %, Barbarie ≈ 50 %, Feu ≈ 40 %. En cours de développement, Barbarie a été réduite après les premiers essais (Fureur 2 → 1,2 %, Folie meurtrière 240 → 200 %, vol de vie 25 → 15 %, Pacte de sang 240 → 210 % et sacrifice 12 → 10 %) et Foudre renforcée (Arc électrique 160 → 180 %, Jugement de foudre 240 → 260 %, Surtension 6 → 8 %)."]],
  ["Équilibrage : ennemis",["Attaque des monstres +14 % environ à tous les niveaux (formule 7 + 2,9 × niv + 0,07 × niv²).","Normal : attaque des boss +15 %.","Héroïque : attaque des monstres ×2,6 (avant ×3,2), PV des boss ×1,6 (avant ×2), attaque des boss ×2,9 (avant ×3,8).","Mythique : attaque des monstres ×2,9 (avant ×3,6), PV des boss ×1,7 (avant ×2,4), attaque des boss ×2,2 (avant ×3,2).","Objectif (simulations avec un équipement du niveau du héros) : en Normal, les boss laissent environ 60 à 90 % des PV ; le Mythique demande un équipement Légendaire +10 et le boss Mythique reste le défi le plus difficile (40 à 80 % de victoires selon la spécialisation avec un équipement Légendaire +10)."]],
  ["Aide et notes",["L’Aide indique les nouveaux plafonds, la recharge des PA et des potions.","Nouvelle mise en page des notes de mise à jour : titres centrés, plus grands et en gras.","Aide : nouvel effet Paralysie et tableau de rareté des affixes."]]
 ]},
 {v:'0.3.0',t:"Combat 2.0 - Stat - PVP",sec:[
  ["Duels PvP",["Nouveau mode « Duel PvP » dans l’onglet Aventure : recherchez un adversaire parmi les joueurs connectés.","Une confirmation s’affiche quand un adversaire est trouvé. Le duel se joue au tour par tour dans une fenêtre au centre de l’écran : PV, PA, compétences et potions des deux joueurs.","À la fin, le nom du vainqueur s’affiche puis un butin de 500 or récompense la victoire.","Défiez directement un ami : cliquez sur son nom dans la liste d’amis, puis sur « Duel ».","Un joueur qui ne joue pas pendant 90 secondes peut être déclaré perdant ; bouton « Abandonner » disponible."]],
  ["Combat",["Points d’action (PA) : 5 de base pour chaque classe. Les compétences coûtent des PA, l’attaque de base est gratuite mais utilisable une seule fois par tour, et chaque unité récupère 1 PA au début de son tour.","Votre héros peut enchaîner plusieurs actions dans le même tour tant qu’il lui reste des PA ; nouveau bouton « Fin de tour ».","Barre de PA segmentée sous la barre de vie de chaque combattant ; le coût en PA est affiché sur chaque compétence.","Nouvelles statistiques : Résistance physique, Résistance magique et résistances au Feu, à la Glace, à la Foudre et à la Terre (en %, plafonnées à 75 %). L’ancienne Résistance devient « Défense magique ».","Compétences élémentaires : Boule de feu (Feu), Éclair en chaîne (Foudre), Météore (Terre) ; côté ennemis, Trait de feu, Crachat toxique et Déferlante. Certains monstres résistent à un élément, d’autres y sont faibles.","Nouveaux affixes de résistance sur l’équipement."]],
  ["Forge",["Nouvelles chances de rareté : Forge ordinaire 80 % Commun / 20 % Magique ; Forge fine 40 % Commun / 50 % Magique / 10 % Rare ; Forge de maître 10 % Magique / 45 % Rare / 45 % Épique ; Forge légendaire 20 % Rare / 70 % Épique / 10 % Légendaire.","Affixes aléatoires : Commun 0, Magique 1, Rare 2, Épique 3, Légendaire 3 + un pouvoir légendaire.","Pouvoir légendaire (écrit en orange) : +6 % de chances de coup critique et +10 % de dégâts critiques. Un pouvoir nommé pour chaque type d’équipement ; les objets légendaires existants le reçoivent aussi."]],
  ["Personnage",["Caractéristiques regroupées en trois catégories : Principale, Secondaire et Résistance. « Défense » devient « Défense physique ».","Les valeurs affichées sont les totaux (base + équipement) ; un bouton affiche le détail entre parenthèses (base + équipement).","« Or trouvé » et « Dégâts bonus » ne sont plus affichés dans la fiche."]],
  ["Amis",["Amis classés en deux catégories : En ligne et Hors ligne.","Chat entre amis : cliquez sur le nom d’un ami puis sur « Chat ». Une pastille rouge signale un nouveau message sur le bouton Amis et sur l’ami concerné."]]
 ]},
 {v:'0.1.1',t:"Fiche de personnage",sec:[
  ["Amis",["Nouveau système d’amis : liste fixée en bas à droite de l’écran, avec le nombre d’amis connectés.","Ajoutez un joueur avec son nom de compte ; il accepte ou refuse la demande. Vous voyez si vos amis sont en ligne et quel personnage ils jouent.","Nom de compte : à la première connexion, chaque joueur choisit un nom unique, commun à tous ses personnages."]],
  ["Personnage",["Les onglets Personnage et Inventaire sont fusionnés dans l’onglet Personnage.","En haut : l’équipement (roue) à gauche et la présentation du héros à droite (portrait, niveau, statistiques avec le bonus d’équipement en vert, ascension).","En dessous : l’inventaire, puis les compétences. La zone de détails s’affiche sous l’équipement quand un objet est sélectionné.","La roue d’équipement est agrandie et occupe toute la hauteur de la présentation du héros."]]
 ]},
 {v:'0.0.9',t:'Entrepôts et débogage',sec:[
  ['Compte',['Connexion par e-mail et mot de passe, ou avec Google (création de compte et mot de passe oublié).','Sauvegarde en ligne : vos personnages et l’or partagé sont liés à votre compte et synchronisés automatiquement entre vos appareils.','« Jouer sans compte » garde la sauvegarde sur l’appareil. À la première connexion, la partie de l’appareil devient celle du compte.','Le compte connecté et un bouton « Se déconnecter » sont affichés en haut à droite du menu.']],
  ['Collecte',['Entrepôt : chaque rang augmente de 100 le stock maximum (affiché en haut de la page) des ressources produites par la zone. Grand entrepôt double ce bonus (+2 000 au maximum).','Les zones ne gardent plus de récoltes en réserve : quand la jauge est pleine, il faut collecter.','En haut de l’arbre de talents, la case « Réserve » est remplacée par « Stock maximum ».']],
  ['Débogage',['Nouvelle section Débogage dans les Options : composants à 0 ou au maximum, or, niveaux et points de compétence, objets divins ou légendaires, inventaire, Aventure, récoltes prêtes, arbres de talents, et remise à zéro complète de la progression du personnage.','Réglages : « Aucun coût » (forge, améliorations, arbres, zones, achats) et « Récoltes accélérées » (une récolte toutes les 5 secondes).']],
 ]},
 {v:'0.0.8',t:'Arbre de collecte',sec:[
  ['Menu',['Le bouton « Menu » en jeu ouvre un menu déroulant : Options, Nouveautés et Changer de personnage.','Options et Nouveautés s’ouvrent depuis la partie, avec un bouton « Retour au jeu ».','« Changer de personnage » demande une confirmation, puis ouvre l’écran de choix des personnages.']],
  ['Collecte',['Les niveaux de zone sont remplacés par un arbre d’améliorations : bouton flèche en haut à droite de chaque zone.','Branches de 10 rangs payés en or : Cadence (+5 % de vitesse par rang), Entrepôt (+1 récolte en réserve) et une branche par ressource de la zone (+15 % de cette ressource par récolte). Chaque branche complète débloque un talent étoilé : +25 % de vitesse, réserve ×2, ou 10 % de chances de doubler cette ressource (Filon de fer, Veine d’or, Clairière fertile, Grand gibier, Géode, Source vive, Glyphe ancien).','L’or dépensé dans les anciens niveaux de zone est remboursé.','Nouvelle mise en page des zones : nom centré en haut, bouton Collecter centré.']],
  ['Équilibrage',['Les branches de ressource donnent maintenant +15 % par rang (+150 % au maximum).','Stock maximum réduit à 1 000 par matériau (au lieu de 10 000).','Coûts de la Forge revus à la baisse : Forge ordinaire ~19 fer et 10 cuirs, Forge légendaire ~115 fer, 56 cuirs, 46 cristaux, 20 essences et 8 runes.','Améliorer, relancer et remplacer une affixe coûtent moins de matériaux (l’or ne change pas).']],
  ['Récoltes',['Les zones ne produisent plus en continu : elles livrent une récolte toutes les 5 minutes (barre et compte à rebours sur chaque zone).','La Forêt ne donne plus de cristaux, les Ruines plus d’essence, et le Marais ne garde que l’essence et les runes.','Récolte de base : 15 fer et 15 or à la Mine ; 9 herbes et 9 cuirs à la Forêt ; 15 cristaux et 1 rune aux Ruines ; 6 essences et 1 rune au Marais.','La branche Cadence réduit le temps entre deux récoltes (jusqu’à environ 2 min 50 avec le talent étoilé).','Chaque zone affiche la quantité de chaque récolte et une grande jauge avec le temps restant ; les jauges de stock par ressource sont retirées.','Quand la jauge est pleine, la zone attend : il faut appuyer sur « Collecter » pour récupérer la récolte et relancer la jauge. La branche Entrepôt permet de garder des récoltes en réserve (+1 par rang, ×2 avec Grand entrepôt).','Niveau de zone : chaque amélioration achetée dans l’arbre augmente le niveau de la zone de 1.','Récolte automatique : se débloque dans l’arbre à partir du niveau de zone 25, puis s’active avec l’engrenage en haut à gauche de la zone (menu déroulant).','Les icônes des ressources de chaque zone sont affichées en bas à gauche.','Les boutons « Collecte auto » et « Tout collecter » sont retirés ; les titres Collecte, Forge et Marchand sont centrés et en gras.','Un point rouge sur l’onglet Collecte signale une récolte prête.']]
 ]},
 {v:'0.0.7',t:'L’Enclume',sec:[
  ['Menu du jeu',['Nouvel écran d’accueil au centre de l’écran : Jouer, Options et Nouveautés.','En jeu, le bouton « Menu » en haut à droite ramène à l’écran d’accueil après une fenêtre de confirmation (Oui / Non). La partie est sauvegardée.','Un point rouge sur « Nouveautés » (et sur le bouton « Menu » en jeu) signale une nouvelle version.','Les Options (sauvegarde) et les Nouveautés sont maintenant accessibles depuis le menu.']],
  ['Personnages',['Jusqu’à 5 personnages, de n’importe quelle classe. « Jouer » ouvre l’écran de choix : jouer, créer ou supprimer un personnage.','Seul l’or est partagé entre les personnages. Inventaire, équipement, matériaux, collecte et progression sont propres à chacun.','Votre partie actuelle devient automatiquement le personnage 1. L’export de sauvegarde contient tous les personnages.']],
  ['Forge',['Forge redessinée (style « Enclume ») : liste des objets à gauche, enclume lumineuse au centre avec le type de forge et le bouton Forger, chances de rareté en barres, coût et dernière création à droite. En Amélioration : roue d’équipement à gauche, objet posé sur l’enclume au centre, actions à droite.']],
  ['Aventure',['Le mode Héroïque demande maintenant d’atteindre le niveau 50. En dessous, le bouton est verrouillé (le mode Mythique aussi).']],
  ['Inventaire',['Zone de détails de retour dans l’Inventaire et la Forge : elle s’affiche uniquement quand un objet est sélectionné, avec ses boutons (équiper, améliorer, détruire…). Sur téléphone, elle apparaît juste sous la grille ou sous le mannequin, et les plages des affixes y sont toujours affichées.','Dans l’Inventaire, la zone de détails est alignée avec la zone du personnage.']]
 ]},
 {v:'0.0.6',t:'Cercle runique',sec:[
  ['Matériaux',['Les matériaux (fer, cuir, herbe, cristal, essence, runes, prismes) quittent l’inventaire : ils sont affichés en haut, à côté de l’or.','Stock maximum : 10 000 par matériau. Les potions restent dans l’inventaire.']],
  ['Forge',['En mode Amélioration, la roue d’équipement s’affiche à gauche : cliquez, glissez ou faites un clic droit sur un emplacement pour améliorer l’objet porté.','Les jambières de soie et de plaque s’appellent désormais simplement « Jambières ».']],
  ['Inventaire',['Nouveau mannequin « cercle runique » pour les deux classes : portrait de la classe au centre, entouré d’anneaux dorés et de runes.','Les 8 emplacements sont disposés en cercle autour du portrait ; les emplacements occupés prennent la couleur de la rareté de l’objet.','Fond de la roue d’équipement éclairci, dans toutes les sections.','Grille réduite à 14 × 5 cases (70 cases). Les objets hors de la nouvelle grille sont replacés automatiquement, ou vendus s’il n’y a plus de place.','En-tête allégé : seul le nom du héros reste, agrandi et en gras, au-dessus du mannequin.','Infobulles d’équipement : maintenez Maj (Shift) pour afficher entre parenthèses grises la plage possible de chaque affixe.']]
 ]},
 {v:'0.0.5',t:'Équilibrage et mode Mythique',sec:[
  ['Combats',['Nouvelle formule de dégâts : la Défense protège moins contre les monstres de haut niveau.','Les monstres frappent plus fort à haut niveau.','Vol de vie plafonné à 20 % et Esquive à 30 % ; ces affixes sont moins puissants.','Les améliorations d’objets donnent +5 % par niveau au lieu de +8 %.']],
  ['Héroïque',['Monstres plus agressifs. Les boss frappent beaucoup plus fort, ont un peu plus de PV et entrent en rage dès le tour 11.']],
  ['Mythique',['Nouvelle difficulté, débloquée en atteignant le dernier boss en mode héroïque.','Monstres niveau 60. Les boss gagnent la Frappe dévastatrice et entrent en rage dès le tour 9.','Récompenses : or, XP et matériaux ×2. Prisme divin à 25 % sur Le Dévoreur. Progression séparée.']],
  ['Personnage',['Feuille de personnage : nom en titre et icône centrée.','Ascension : niveau maximum requis. Premier palier : 5 000 or et 5 Prismes divins (le coût augmente à chaque palier).','Les compétences apprises ne peuvent plus être retirées : toutes les compétences actives apprises sont utilisées en combat.']],
  ['Inventaire',['Nom du héros centré avec l’icône de classe en dessous.','Bouton sous le mannequin pour afficher ou masquer les statistiques.','Caractéristiques complètes sur une seule colonne, avec le bonus de l’équipement en vert.','Zone Détail supprimée ; les explications de glisser-déposer sont sous le mannequin.','Nouveau mannequin illustré pour le Sorcier, avec les emplacements posés sur le personnage.']],
  ['Équipement',['Nouvel emplacement : les Jambières (2×3 cases, vie et défense). Une version pour chaque classe, à fabriquer à la Forge.']],
  ['Aide',['Nouvel onglet Aide : statistiques, calcul des dégâts, afflictions, bonus et malus, rage, difficultés, potions, rareté et ascension.']],
  ['Interface',['Écran Aventure refait : héros à gauche en colonne, « Choix de zone » à droite avec la difficulté, les zones en cadres rectangulaires puis le niveau de la zone.','Nouveaux portraits illustrés du Guerrier et du Sorcier, dans la feuille de personnage et dans l’Aventure.','Dans l’Aventure, le nom du héros est affiché en titre au-dessus du portrait.']]
 ]},
 {v:'0.0.4',t:'Héroïque et Marchand',sec:[
  ['Aventure',['Nouveau mode Héroïque : monstres niveau 50, boss avec +150 % de puissance et de résistance. Progression séparée du mode normal.']],
  ['Marchand',['Nouvel onglet Marchand entre Inventaire et Forge.','Potions de vie, de résistance, de force (Guerrier), d’intelligence (Sorcier), Élixir de savoir (+50 % XP) et Philtre de fortune (+50 % or et matériaux).','Les potions se boivent en combat sans utiliser votre tour.','Infobulle au survol des potions en combat : effet, quantité en stock et utilisation restante.','La potion de l’autre classe reste visible chez le Marchand mais ne peut pas être achetée (Intelligence pour le Guerrier, Force pour le Sorcier).']],
  ['Classes',['Le Guerrier n’a plus d’Intelligence et le Sorcier n’a plus de Force, bijoux compris.']]
 ]},
 {v:'0.0.3',t:'Classes, inventaire et objets divins',sec:[
  ['Classes',['Deux classes : Guerrier et Sorcier (le Voleur et le Clerc disparaissent).','Attaque et Magie deviennent Force et Intelligence.','Chaque arme et armure est réservée à une classe : épée, heaume, cuirasse et bottes pour le Guerrier ; bâton, capuche, robe et sandales pour le Sorcier. Anneaux et amulettes sont communs.','La Forge ne fabrique que l’équipement de votre classe.']],
  ['Équipement',['Stats fixes : Force ou Intelligence sur les armes, vie et défense sur les armures. Les bijoux n’ont que des affixes aléatoires.','Affixes Résistance et Butin trouvé supprimés.','Niveau d’objet affiché sur chaque fiche. À la Forge, il dépend du type de forge (1-15, 10-30, 25-45, 40-53) et non plus du niveau du héros.','Nouvelle rareté Divin : 6 affixes, stats ×1,5.','Nouveau composant : le Prisme divin, lâché par Le Dévoreur (10 %). Ajouté à la forge légendaire, il crée un objet Divin de niveau 60.','L’équipement ne s’obtient plus qu’à la Forge.']],
  ['Inventaire',['Grille de 17 × 6 cases façon Path of Exile : arme 1×5, armure 2×3, casque et bottes 2×2, bijoux et matériaux 1×1.','Piles de matériaux jusqu’à 500.','Caractéristiques affichées sans équipement, avec le bonus de l’équipement en vert.','Point rouge sur l’onglet quand un nouvel objet arrive.']],
  ['Collecte',['Cristaux ajoutés au Marais des brumes, aux Ruines et à la Forêt (10/min, max 100).','Collecte automatique quand une ressource atteint sa limite.','Alerte « Inventaire plein » avec point rouge sur l’onglet Collecte.','Caches supprimées.']],
  ['Personnage',['Niveau maximum : 50.','Notification au passage de niveau et point rouge sur l’onglet Personnage.','L’onglet Personnage affiche les compétences à la place de l’équipement.']],
  ['Interface',['Réglages déplacés dans l’engrenage en haut à droite.','Nouvel onglet Nouveautés avec le journal des versions.']]
 ]},
 {v:'0.0.2',t:'Inventaire, Forge et Collecte',sec:[
  ['Inventaire',['Onglet Inventaire avec rangement par glisser-déposer et tri par nom ou quantité.','Les matériaux deviennent des objets dans l’inventaire.','Mannequin d’aventurier : glisser-déposer ou clic droit pour équiper.','Destruction d’objets, seul ou en sélection multiple (25 % des ressources rendues).']],
  ['Forge',['Forge refaite : modes Forge et Amélioration, choix du type de forge avec des flèches.','Case d’amélioration à remplir par glisser-déposer ou clic droit.']],
  ['Collecte',['Les Chantiers deviennent la Collecte : La Mine, Forêt Enchantée, Ruines englouties, Marais des brumes.','Nouveau matériau : Herbe enchantée. Production réduite et stock limité.']]
 ]},
 {v:'0.0.1',t:'Première version',sec:[
  ['Jeu',['Création du héros, combats au tour par tour, cinq zones et leurs boss.','Forge, améliorations d’objets, compétences et ascension.','Sauvegarde automatique, export et import.']]
 ]},
];
